 const n=$('frn_'+id);if(n){const q=$('frq_'+id).value;
  n.textContent=!q?'':ms===null?'not a regex':!ms.length?'no results':((cur!=null?cur+1:'?')+' of '+ms.length+(ms.length>=FIND_MAX?'+':''));}}
