 if(cost!=null)facts.push('cost '+planNum(cost));
 ['using_index','using_filesort','using_temporary_table','using_join_buffer','using_index_condition','using_MRR'].forEach(f=>{if(t[f])facts.push(f.replace(/^using_/,'').replace(/_/g,' '));});
 return '<div class="pcard '+k[0]+'"><b>'+esc(t.table_name||'?')+'</b> <span class="pacc">'+esc(a)+(k[1]?' - '+esc(k[1]):'')+'</span>'+
  (facts.length?'<div class="pfacts">'+esc(facts.join(' · '))+'</div>':'')+
  (t.attached_condition?'<div class="pcond" title="'+esc(t.attached_condition)+'">where '+esc(clip(t.attached_condition,160))+'</div>':'')+'</div>';}
// The <li>s for what an object holds: a table's card, or a branch for each step inside it.
function planItems(v){if(!v||typeof v!=='object')return '';
 const kids=Object.keys(v).filter(k=>!PLAN_SKIP.has(k)&&v[k]&&typeof v[k]==='object').map(k=>planNode(k,v[k])).join('');
 if(v.table_name)return '<li>'+planTable(v)+(kids?'<ul>'+kids+'</ul>':'')+'</li>';
 return kids;}
function planNode(k,v){if(k==='table')return planItems(v);
 if(Array.isArray(v)){const inner=v.map(planItems).join('');return inner?'<li><div class="pstep">'+esc(PLAN_STEP[k]||k.replace(/_/g,' '))+'</div><ul>'+inner+'</ul></li>':'';}
 const facts=[];if(v.select_id!=null)facts.push('select #'+v.select_id);
 const qc=v.cost_info&&v.cost_info.query_cost!=null?v.cost_info.query_cost:(k==='query_block'?v.cost:null);if(qc!=null)facts.push('cost '+planNum(qc));
 ['using_filesort','using_temporary_table'].forEach(f=>{if(v[f])facts.push(f.replace(/^using_/,'').replace(/_/g,' '));});
 const inner=planItems(v);
 return '<li><div class="pstep">'+esc(PLAN_STEP[k]||k.replace(/_/g,' '))+(facts.length?' <span class="pfacts">'+esc(facts.join(' · '))+'</span>':'')+'</div>'+(inner?'<ul>'+inner+'</ul>':'')+'</li>';}
// The whole drawing: a line saying what matters most - how many tables are read in full - then
// the tree, then the JSON itself for anyone who wants it.
function planHtml(json){let plan;try{plan=typeof json==='string'?JSON.parse(json):json;}catch(e){return '<div class="muted">The server did not answer with a plan this can read.</div><pre>'+esc(String(json))+'</pre>';}
 const scans=[];(function walk(o){if(!o||typeof o!=='object')return;if(Array.isArray(o)){o.forEach(walk);return;}if(o.table_name&&planAccess(o)==='ALL')scans.push(o.table_name);Object.keys(o).forEach(k=>walk(o[k]));})(plan);
 const head=scans.length?'<div class="psum bad">'+scans.length+' table'+(scans.length===1?' is':'s are')+' read in full: '+esc(scans.join(', '))+'</div>':'<div class="psum good">No table is read in full.</div>';
 return head+'<ul class="plan">'+Object.keys(plan).map(k=>planNode(k,plan[k])).join('')+'</ul><details class="pjson"><summary>The plan as the server gave it (JSON)</summary><pre>'+esc(JSON.stringify(plan,null,2))+'</pre></details>';}
async function planShow(id,stmt){const t=T(id);if(!t)return;
 await sessFree(t);
 const r=await api('/api/query',{sql:'EXPLAIN FORMAT=JSON '+stmt,db:dbOf(t),session:sessOf(t)});
 $('planTitle').textContent='Query plan - '+t.title;
 $('planBody').innerHTML=r.ok&&r.rows&&r.rows.length?planHtml(r.rows[0][0]):'<div class="unone">'+esc(r.error||'The server gave no plan for this statement.')+'</div>';
 show('mPlan');}
// ---- a chart of the result ----
// Bars or a line from the rows the grid shows, in its order and with its filters - so sorting or
// filtering the grid is how the chart is shaped, and the grid beside it is its table. The first
// column that is not numbers is the axis; the columns of numbers are the series, coloured in one
// fixed order (validated for colour vision and both themes) and never more than eight.
const CHART_MAX_ROWS=500,CHART_MAX_SERIES=8;let _chartTab=null;
function chartIsNum(v){return v!=null&&v!==''&&/^-?(\d+\.?\d*|\.\d+)(e[-+]?\d+)?$/i.test(String(v).trim());}
// Which columns hold numbers: nine in ten of the values that are there, and at least one.
function chartNumericCols(cols,rows){return cols.map((c,ci)=>{let n=0,ok=0;rows.forEach(r=>{const v=r[ci];if(v==null||v==='')return;n++;if(chartIsNum(v))ok++;});return n>0&&ok/n>=0.9;});}
// Round steps (1, 2 or 5 times a power of ten) covering lo..hi in about count of them.
function chartTicks(lo,hi,count){if(!(hi>lo))hi=lo+1;const raw=(hi-lo)/Math.max(1,count),mag=Math.pow(10,Math.floor(Math.log10(raw))),f=raw/mag,step=(f<=1?1:f<=2?2:f<=5?5:10)*mag;
 const out=[];for(let v=Math.floor(lo/step)*step;v<=Math.ceil(hi/step)*step+step/2;v+=step)out.push(+v.toPrecision(12));return out;}
function chartFmt(v){const a=Math.abs(v);return a>=1e9?+(v/1e9).toPrecision(3)+'B':a>=1e6?+(v/1e6).toPrecision(3)+'M':a>=1e4?+(v/1e3).toPrecision(3)+'k':String(+(+v).toPrecision(6));}
// A bar with its data end rounded and its baseline end square, growing up or down from y0.
function chartBar(x,top,w,h,r,up){if(h<=0)return 'M'+x+' '+top+'h'+w;const R=Math.min(r,w/2,h),b=top+h;
 return up?'M'+x+' '+b+'V'+(top+R)+'Q'+x+' '+top+' '+(x+R)+' '+top+'H'+(x+w-R)+'Q'+(x+w)+' '+top+' '+(x+w)+' '+(top+R)+'V'+b+'Z'
          :'M'+x+' '+top+'V'+(b-R)+'Q'+x+' '+b+' '+(x+R)+' '+b+'H'+(x+w-R)+'Q'+(x+w)+' '+b+' '+(x+w)+' '+(b-R)+'V'+top+'Z';}
// The picture: {labels, series:[{name, values}], type:'bar'|'line', width, height} -> SVG.
function chartSvg(o){const W=o.width,H=o.height,m={l:56,r:14,t:10,b:30},pw=W-m.l-m.r,ph=H-m.t-m.b,n=Math.max(1,o.labels.length);
 const all=o.series.flatMap(x=>x.values).filter(v=>v!=null);
 // Bars stand on zero; a line may start where its data does.
 let lo=o.type==='line'&&all.length?Math.min(...all):Math.min(0,...all),hi=o.type==='line'&&all.length?Math.max(...all):Math.max(0,...all);
 const ticks=chartTicks(lo,hi,5),y0=ticks[0],y1=ticks[ticks.length-1],Y=v=>m.t+ph-(v-y0)/((y1-y0)||1)*ph,base=Y(Math.max(y0,Math.min(0,y1)));
 const band=pw/n,cx=i=>m.l+band*(i+.5);
 let s='<svg class="chart" viewBox="0 0 '+W+' '+H+'" width="'+W+'" height="'+H+'" role="img" aria-label="'+esc(o.series.map(x=>x.name).join(', '))+'">';
 ticks.forEach(t=>{const y=Y(t).toFixed(1);s+='<line class="cgrid" x1="'+m.l+'" x2="'+(W-m.r)+'" y1="'+y+'" y2="'+y+'"/><text class="caxis" x="'+(m.l-7)+'" y="'+(+y+4)+'" text-anchor="end">'+esc(chartFmt(t))+'</text>';});
 // As many axis labels as fit side by side, never on top of each other.
 const longest=Math.min(14,Math.max(1,...o.labels.map(l=>String(l==null?'NULL':l).length))),every=Math.max(1,Math.ceil((longest*6.6+10)/band));
 o.labels.forEach((l,i)=>{if(i%every)return;let t=String(l==null?'NULL':l);if(t.length>14)t=t.slice(0,13)+'…';s+='<text class="caxis" x="'+cx(i).toFixed(1)+'" y="'+(H-m.b+16)+'" text-anchor="middle">'+esc(t)+'</text>';});
 const k=o.series.length;
 if(o.type==='bar'){const gap=2,inner=Math.min(band*0.8,k*24+(k-1)*gap),bw=Math.max(1,(inner-(k-1)*gap)/k);
  o.series.forEach((se,si)=>se.values.forEach((v,i)=>{if(v==null)return;const x=m.l+band*i+(band-inner)/2+si*(bw+gap),y=Y(v);
   s+='<path class="cmark s'+(si+1)+'" d="'+chartBar(+x.toFixed(2),+Math.min(y,base).toFixed(2),+bw.toFixed(2),+Math.abs(base-y).toFixed(2),4,v>=0)+'"/>';}));}
 else o.series.forEach((se,si)=>{let d='';se.values.forEach((v,i)=>{if(v==null)return;d+=(d?'L':'M')+cx(i).toFixed(1)+' '+Y(v).toFixed(1);});
  s+='<path class="cline s'+(si+1)+'" d="'+d+'"/>';
  if(o.labels.length<=60)se.values.forEach((v,i)=>{if(v!=null)s+='<circle class="cdot s'+(si+1)+'" cx="'+cx(i).toFixed(1)+'" cy="'+Y(v).toFixed(1)+'" r="4"/>';});});
 s+='<line class="cbase" x1="'+m.l+'" x2="'+(W-m.r)+'" y1="'+base.toFixed(1)+'" y2="'+base.toFixed(1)+'"/>';
 s+='<line class="cross" x1="0" x2="0" y1="'+m.t+'" y2="'+(m.t+ph)+'" style="display:none"/>';
 for(let i=0;i<o.labels.length;i++)s+='<rect class="chit" data-i="'+i+'" x="'+(m.l+band*i).toFixed(2)+'" y="'+m.t+'" width="'+band.toFixed(2)+'" height="'+ph+'"/>';
 return s+'</svg>';}
function chartOpen(id){const t=T(id);if(!t||!t.cols||!t.cols.length)return;
 const rows=viewIndices(id).slice(0,CHART_MAX_ROWS).map(ri=>t.rows[ri]),num=chartNumericCols(t.cols,rows);
 if(!num.some(Boolean)){toast('There is no column of numbers in this result to chart.',true);return;}
 _chartTab=id;const xi=num.findIndex(b=>!b);let left=CHART_MAX_SERIES;
 $('chartX').innerHTML='<option value="-1">Row number</option>'+t.cols.map((c,ci)=>'<option value="'+ci+'"'+(ci===xi?' selected':'')+'>'+esc(c)+'</option>').join('');
 $('chartSeries').innerHTML=t.cols.map((c,ci)=>num[ci]?'<label class="ck"><input type="checkbox" value="'+ci+'"'+(ci!==xi&&left-->0?' checked':'')+' onchange="chartDraw()"> '+esc(c)+'</label>':'').join('');
 $('chartTitle').textContent='Chart - '+t.title;show('mChart');chartDraw();}
function chartDraw(){const id=_chartTab,t=T(id),box=$('chartPlot');if(!t||!box)return;
 const shown=viewIndices(id),rows=shown.slice(0,CHART_MAX_ROWS).map(ri=>t.rows[ri]),xi=+$('chartX').value,type=$('chartType').value;
 const picked=[...$('chartSeries').querySelectorAll('input:checked')].map(b=>+b.value).filter(ci=>ci!==xi);
 const labels=rows.map((r,i)=>xi<0?String(i+1):r[xi]);
 const series=picked.slice(0,CHART_MAX_SERIES).map(ci=>({name:t.cols[ci],values:rows.map(r=>chartIsNum(r[ci])?+r[ci]:null),raw:rows.map(r=>r[ci])}));
 $('chartNote').textContent=(shown.length>CHART_MAX_ROWS?'The first '+CHART_MAX_ROWS+' of '+fmtCount(shown.length)+' rows':fmtCount(rows.length)+' row'+(rows.length===1?'':'s'))+', in the grid\'s order and with its filters.'+(picked.length>CHART_MAX_SERIES?' Eight series at most - the first eight picked are drawn.':'');
 if(!series.length){box.innerHTML='<div class="muted" style="padding:20px">Pick a column of numbers to chart.</div>';$('chartLegend').innerHTML='';return;}
 box.innerHTML=chartSvg({labels,series,type,width:Math.max(360,box.clientWidth-2),height:Math.max(220,box.clientHeight-2)})+'<div class="ctip" id="chartTip"></div>';
 $('chartLegend').innerHTML=series.length>1?series.map((x,i)=>'<span class="cleg"><i class="s'+(i+1)+'"></i>'+esc(x.name)+'</span>').join(''):'';
 const svg=box.querySelector('svg'),tip=$('chartTip'),cross=svg.querySelector('.cross');
 svg.querySelectorAll('.chit').forEach(r=>{
  r.onmousemove=e=>{const i=+r.dataset.i,x=(+r.getAttribute('x')+(+r.getAttribute('width'))/2).toFixed(1);cross.setAttribute('x1',x);cross.setAttribute('x2',x);cross.style.display='';
   tip.innerHTML='<b>'+esc(labels[i]==null?'NULL':labels[i])+'</b>'+series.map((x2,si)=>'<div><i class="s'+(si+1)+'"></i>'+esc(x2.name)+' <span>'+esc(x2.raw[i]==null?'NULL':x2.raw[i])+'</span></div>').join('');
   tip.style.display='block';const b=box.getBoundingClientRect();tip.style.left=Math.max(0,Math.min(e.clientX-b.left+14,b.width-tip.offsetWidth-4))+'px';tip.style.top=Math.max(0,e.clientY-b.top-tip.offsetHeight-8)+'px';};
  r.onmouseleave=()=>{tip.style.display='none';cross.style.display='none';};});}
// Drawn again when its window changes size (maximize, a drag at the corner).
if(typeof ResizeObserver!=='undefined')document.addEventListener('DOMContentLoaded',()=>{const b=$('chartPlot');if(b){let w=0;new ResizeObserver(()=>{if(b.clientWidth&&b.clientWidth!==w&&$('mChart').classList.contains('show')){w=b.clientWidth;chartDraw();}}).observe(b);}});
// Heuristic SQL formatter, built on the SAME tokenizer as the syntax highlighter (hl()), so it
// can never touch the CONTENT of a string, comment, or identifier - only the whitespace and line
// breaks BETWEEN tokens. Not a full parser (deeply nested subqueries won't get perfect
// indentation), but that limitation is purely cosmetic: the one thing this is guaranteed to
// never do is alter what the query actually says, since every non-whitespace token passes
// through completely unchanged.
// Each token has to come out exactly as it went in, because only the space between tokens is
// changed. The tokens used to be cut too small, and a space put into the middle of one changed the
// query: 'O''Brien' became 'O' 'Brien' (two strings, which MySQL joins into OBrien), 1e5 became
// "1 e5" and 0x41 "0 x41" (a number and a column alias), >= became "> =" (a syntax error), größe
// fell apart at the ö, and @var at the @. A "--" or "#" comment ran on into the next token,
// so the line after it - "AND b = 2" of a DELETE's WHERE - became part of the comment.
function formatSql(sql){
 const W='[A-Za-z0-9_$\\u0080-\\uffff]';
 const STR="'(?:[^'\\\\]|\\\\[\\s\\S]|'')*'";
 const re=new RegExp('(\\/\\*[\\s\\S]*?\\*\\/|(?:--(?=\\s|$)|#)[^\\n]*)'
  +'|([xXbBnN]?'+STR+'|"(?:[^"\\\\]|\\\\[\\s\\S]|"")*"|`(?:[^`]|``)*`)'
  +'|(0x[0-9A-Fa-f]+(?!'+W+')|0b[01]+(?!'+W+')|(?:\\d+\\.?\\d*|\\.\\d+)(?:[eE][+-]?\\d+)?(?!'+W+'))'
  +'|(@@?(?:[A-Za-z0-9_$.\\u0080-\\uffff]+|`(?:[^`]|``)*`|'+STR+')|'+W+'+)'
  +'|(<=>|->>|->|<>|!=|<=|>=|:=|\\|\\||&&|<<|>>|[\\s\\S])','g');
 let m,toks=[];
 while((m=re.exec(sql))){
  if(m[1])toks.push({t:'comment',v:m[1]});
  else if(m[2])toks.push({t:'str',v:m[2]});
  else if(m[3])toks.push({t:'num',v:m[3]});
  else if(m[4])toks.push({t:'word',v:m[4]});
  else if(!/\s/.test(m[5]))toks.push({t:'ch',v:m[5]});
 }
 const BREAK1=new Set(['select','from','where','set','values','union']);
 const COMPOUND={group:'by',order:'by',left:'join',right:'join',inner:'join',full:'join',union:'all',insert:'into','delete':'from'};
 let out='',depth=0;
 for(let i=0;i<toks.length;i++){
  const tok=toks[i];
  if(tok.t==='ch'&&tok.v==='('){depth++;out+=(out&&!/[\s(]$/.test(out)?' ':'')+'(';continue;}
  if(tok.t==='ch'&&tok.v===')'){depth=Math.max(0,depth-1);out+=')';continue;}
  if(tok.t==='ch'&&(tok.v===','||tok.v===';'||tok.v==='.')){out+=tok.v;continue;}
  const lw=tok.t==='word'?tok.v.toLowerCase():'';
  let isBreak=tok.t==='word'&&depth===0&&(BREAK1.has(lw)||lw==='join'||lw==='having'||lw==='limit'||lw==='on');
  if(tok.t==='word'&&depth===0&&COMPOUND[lw]&&toks[i+1]&&toks[i+1].t==='word'&&toks[i+1].v.toLowerCase()===COMPOUND[lw]){isBreak=true;}
  const prevTok=toks[i-1];
  const isCompoundContinuation=tok.t==='word'&&prevTok&&prevTok.t==='word'&&COMPOUND[prevTok.v.toLowerCase()]===lw;
  const afterDot=prevTok&&prevTok.t==='ch'&&prevTok.v==='.';
  if(isBreak&&out.trim().length&&!isCompoundContinuation&&!afterDot){
   out=out.replace(/[ \t]+$/,'');
   out+=(out.endsWith('\n')||out.length===0?'':'\n')+tok.v;
  }else{
   if(out.length&&!out.endsWith('\n')&&!out.endsWith('(')&&!out.endsWith('.')&&tok.v!==','){
    const prevCh=out[out.length-1];
    if(!/\s/.test(prevCh)&&prevCh!=='('&&prevCh!=='.')out+=' ';
   }
   out+=tok.v;
  }
  // A line comment ends at the end of its line; whatever follows starts a new one.
  if(tok.t==='comment'&&!tok.v.startsWith('/*'))out+='\n';
 }
 return out.trim();
}
// A script with DELIMITER lines is left as it is: the delimiter is whatever the line says, and
// nothing here knows where a routine body starts or ends. The text is replaced as an edit, so
// Ctrl+Z brings the original back.
function formatTabSql(id){const ta=$('ed_'+id);
 if(/^[ \t]*delimiter[ \t]/im.test(ta.value)){toast('A script with DELIMITER lines is not formatted - the routine bodies in it would be.',true);return;}
 const next=formatSql(ta.value);if(next===ta.value)return;
 ta.focus();ta.select();let ok=false;try{ok=document.execCommand('insertText',false,next);}catch(e){}
 if(!ok||ta.value!==next)ta.value=next;
 syncHl(id);markEdited(id);log('Formatted query.');}
async function runSel(id){
 const ta=$('ed_'+id);
 const sel=ta.value.substring(ta.selectionStart,ta.selectionEnd).trim();
 if(sel){await runSql(id,sel);return;}
 // No selection: run whichever statement the cursor is currently positioned within, rather
 // than falling back to the whole editor - matches the "execute statement at cursor"
 // convention most SQL editors (DBeaver, DataGrip, SSMS) already use. A selection, when
 // present, is always honored above and takes priority over this.
 const pos=ta.selectionStart;
 const stmts=splitStmts(ta.value,true);
 const hit=stmts.find(s=>pos>=s.start&&pos<=s.end);
 await runSql(id,hit?hit.text:ta.value);
}
// Server errors already start with "ERROR 1146 (42S02): ...", so prefixing them produced
// "ERROR: ERROR 1146 ...". Only add the prefix when the message does not carry one.
function logErr(msg){ msg=String(msg==null?'':msg); return /^ERROR\b/.test(msg)?msg:('ERROR: '+msg); }
// A table-view or DDL tab is pinned to the schema it was opened from, so browsing elsewhere
// cannot silently retarget its generated query. Once the user replaces that query with their
// own SQL, the reasoning no longer holds: it is an ordinary query now and should run against
// the schema selected in the sidebar, like any other query tab. Reverting the text back to the
// generated query pins it again.
function markEdited(id){
 const t=T(id), ta=$('ed_'+id);
 if(!t||!ta||!(t.table||t.ddl))return;
 const edited=(ta.value!==(t.genSql||''));
 if(edited!==!!t.sqlEdited){ t.sqlEdited=edited; if(activeTab===id) updateSchemaBadge(id); }
}
// The name in an "Unknown database" error, or null. Both servers word it the same way.
function missingDatabase(err){const m=/Unknown database '([^']+)'/i.exec(String(err==null?'':err));return m?m[1]:null;}
// A schema can vanish while the app is pointed at it - dropped from another client, or by a script
// in another tab - and every query then fails with that error while the tree still lists it, which
// reads as the app being broken rather than the database being gone. The list is reloaded and the
// selection let go, once, saying so.
//
// Only for the database the APP chose to run in. A name inside the user's own SQL is theirs to fix,
// and reloading the tree under them for a typo would be noise. A tab bound to a table in the vanished
// database is left alone as well: re-pointing it at some other schema would be a silent lie about
// what it is showing.
async function schemaGoneNote(id,err){
 const gone=missingDatabase(err);
 if(!gone)return false;
 const t=T(id);
 if(!t||gone!==dbOf(t))return false;
 await loadSchemas();
 // Still listed: it exists and something else was wrong - a permission, a race with its creation.
 if((window.allSchemas||[]).indexOf(gone)>=0)return false;
 if(curSchema===gone){curSchema=null;updateSchemaBadge(id);}
 if($('objdb')&&$('objdb').textContent===gone)clearObjectsPanel();
 toast('The database '+gone+' no longer exists. The list of databases has been refreshed, and none is selected.',true);
 log('The database '+gone+' no longer exists - the list of databases has been refreshed.');
 return true;
}
function dbOf(t){ if(t&&(t.table||t.ddl)&&!t.sqlEdited)return t.db||curSchema||null; /* table-view + DDL tabs keep their own schema, until their SQL is edited - see markEdited() */ return curSchema||(t&&t.db)||null; /* plain query tabs follow the selected sidebar schema */ }
// Whether a script's results are all worth showing: it calls a procedure, or has more than one
// statement that returns rows. Both used to show nothing but the last SELECT - a procedure's results
// and every earlier SELECT were run and thrown away.
function scriptShowsResults(stmts){
 const heads=stmts.map(s=>sqlHead(s));
 if(heads.some(h=>/^call\b/i.test(h)))return true;
 if(heads.filter(h=>/^(select|show|describe|desc|explain|with|table|values)\b/i.test(h)).length>1)return true;
 // A script that ends in its one SELECT otherwise runs in two steps on two connections (see runSql),
 // and whatever belongs to a connection did not carry over: "UPDATE ...; SELECT ROW_COUNT()" gave -1,
 // "INSERT ...; SELECT LAST_INSERT_ID()" 0, "SET @x:=5; SELECT @x" NULL, and a temporary table was
 // not there. Such a script runs on one connection, as this path does, at the cost of paging.
 if(stmts.length>1&&!stmts.slice(0,-1).every(s=>/^use\s+\S/i.test(sqlHead(s)))){
  const bare=sqlBlankStringsAndComments(stmts.join('\n'));
  if(/@[A-Za-z_$`'"]|\b(row_count|last_insert_id|found_rows)\s*\(|\btemporary\b|\b(prepare|execute|deallocate)\s|\b(start\s+transaction|begin|lock\s+tables?)\b/i.test(bare))return true;
 }
 return false;
}
// Runs such a script on one connection and shows each result in a tab of its own. These grids
// are read-only: a result of a script is not tied to one table's rows.
async function runScriptResults(id,sql,reqId,seq){
 const t=T(id);const st=$('st_'+id);const stale=()=>!T(id)||T(id).runSeq!==seq;
 const stmts=splitStmts(sql).filter(s=>!isCommentOnly(s));
 const writes=stmts.some(s=>!/^(select|show|describe|desc|explain|with|table|values|use)\b/i.test(sqlHead(s)));
 if(writes&&roBlock()){st.className='status';st.textContent='Read-only mode: statement blocked.';return;}
 const r=await api('/api/script-results',{sql,db:dbOf(t),requestId:reqId,maxRows:PAGE_BATCH,session:sessOf(t)},t.abortCtrl.signal);
 if(r.aborted){if(!stale()){st.className='status';st.textContent='Query cancelled.';}return;}
 if(stale())return;
 t.table=null;t.pk=null;t.pending=null;t.cursorId=null;t.cursorReqId=null;t.hasMore=false;t.exact=false;
 {const eb=$('edit_'+id);eb.style.display='none';}
 const selb=$('selbtn_'+id);if(selb)selb.innerHTML='';
 t.resultSets=r.results||[];
 if(t.resultSets.length){showResultSet(id,0);}
 else{t.cols=[];t.rows=[];$('res_'+id).innerHTML='';renderResultSetTabs(id);updatePager(id);const ra0=$('resultActions_'+id);if(ra0)ra0.style.display='none';}
 const n=t.resultSets.length;
 if(r.ok){st.className='status';st.textContent='OK. '+stmts.length+' statement(s) executed, '+n+' result(s).';log('SCRIPT OK ('+stmts.length+' statements, '+n+' results)');}
 else{st.className='status err';st.textContent=(r.error||'Failed.')+(n?' - showing the '+n+' result(s) produced before it.':'');log(logErr(r.error||'Failed.'));}
 if(writes&&t.db)loadObjects(t.db);
}
function showResultSet(id,i){
 const t=T(id);if(!t||!t.resultSets||!t.resultSets[i])return;
 const rs=t.resultSets[i];t.resultIdx=i;
 t.cols=rs.columns;t.rows=rs.rows;t.binCols=rs.binaryCols||[];t.bitCols=rs.bitCols||null;
 t.filters={};t.sortCol=-1;t.sortDir=1;t.selected=new Set();t._total=null;
 renderResultSetTabs(id);
 const ra=$('resultActions_'+id);if(ra)ra.style.display=t.cols.length?'inline-flex':'none';
 if(!t.cols.length){$('res_'+id).innerHTML='<div class="muted" style="padding:8px">No rows. (The column names of this result are not available: it came from a procedure, or after a USE.)</div>';}
 else renderGrid(id);
 updatePager(id);
}
function renderResultSetTabs(id){
 const t=T(id);const el=$('rsets_'+id);if(!el)return;
 const sets=(t&&t.resultSets)||[];const cur=sets[t&&t.resultIdx||0];
 if(!sets.length||(sets.length===1&&!cur.truncated)){el.style.display='none';el.innerHTML='';return;}
 el.style.display='flex';
 // With a search in the box, each result says how many of its rows hold the text.
 const q=t.search?String(t.search).toLowerCase():'';
