      const scriptR=await api('/api/script',{sql:leadingSql,db:dbOf(t),session:sessOf(t)},t.abortCtrl.signal);
      if(scriptR.aborted){if(T(id)){st.className='status';st.textContent='Query cancelled.';}return;}
      if(stale())return;
