function txReadsOnly(sql){return !String(sql||'').replace(/\/\*[\s\S]*?\*\/|--[^\n]*|#[^\n]*/g,' ').split(';').some(x=>{
 const w=(x.trim().match(/^[A-Za-z]+/)||[''])[0].toUpperCase();return w&&!['SELECT','SHOW','DESCRIBE','DESC','EXPLAIN','USE','HELP','SET'].includes(w);});}
