 const pad=n=>String(n).padStart(2,'0'),hm=d=>pad(d.getHours())+':'+pad(d.getMinutes())+':'+pad(d.getSeconds());
 const changed=log.reduce((a,e)=>a+(e.ok&&e.affected!=null?+e.affected:0),0),failed=log.filter(e=>e.ok===false).length;
