   if(isFk)svg+='<rect x="'+p.x+'" y="'+rowY+'" width="3" height="'+rowH+'" fill="var(--erd-line,#7aa8d8)"/>';
   const color=isPk?'var(--erd-pk,#5dcaa5)':(isFk?'var(--erd-fk,#8fb8e8)':'var(--fg,#ccc)');
   const weight=isPk?'700':'400';
   const titleTag=fkInfo?('<title>References '+esc(fkInfo.refTbl)+'.'+esc(fkInfo.refCol)+'</title>'):'';
   svg+='<text x="'+(p.x+8)+'" y="'+yy+'" fill="'+color+'" font-size="11" font-weight="'+weight+'">'+esc(label)+titleTag+'</text>';
  });
  svg+='</g>';
 });
 svg+='</svg>';
 $('erdBox').innerHTML=svg;
 {const st=$('erdStatus');if(st&&focus){st.innerHTML='Showing <b>'+esc(focus)+'</b> and what it is related to ('+(names.length-1)+' table(s)). <a href="#" style="color:var(--accent)" onclick="erdFocusTable(null);return false">Show all tables</a>';}}
 erdApplyZoomStyle();
 show('mErd');
}
async function openErd(db){
 $('erdFind').value='';window._erdFocus=null;
 window._erdPos=Object.create(null);
 const r=await api('/api/schema-erd',{db});
 if(!r.ok){toast(r.error||'Could not load the database.',true);return;}
 $('erdTitle').textContent='ER diagram - '+db;
 window._erdRawData={db,r};
 erdRender();
}
// A global Escape-key handler elsewhere in the app closes the topmost open modal by directly
// toggling its 'show' class, bypassing any modal-specific close button entirely - so rather than
// trying to intercept every possible way this modal could close (Close button, Escape, any
// future addition), the timer checks on EVERY tick whether the modal is still actually visible,
// and stops itself the moment it isn't. This is what keeps the interval from silently running
// forever in the background after the dialog is gone by some path other than its own button.
let _plAutoRefreshTimer=null;
function plToggleAutoRefresh(){
 if(_plAutoRefreshTimer){clearInterval(_plAutoRefreshTimer);_plAutoRefreshTimer=null;}
 if($('plAutoRefresh')&&$('plAutoRefresh').checked){
  _plAutoRefreshTimer=setInterval(()=>{
   const m=$('mProcessList');
   if(!m||!m.classList.contains('show')){clearInterval(_plAutoRefreshTimer);_plAutoRefreshTimer=null;return;}
   refreshProcessList();
  },3000);
 }
}
async function openProcessList(){show('mProcessList');await refreshProcessList();plToggleAutoRefresh();}
async function refreshProcessList(){
 $('plStatus').textContent='Loading\u2026';
 const r=await api('/api/process-list',{});
 if(!r.ok){$('plStatus').textContent='';$('plGrid').innerHTML='<div class="muted" style="padding:8px">'+esc(r.error||'Could not load process list.')+'</div>';return;}
 const idIdx=r.columns.findIndex(c=>c.toLowerCase()==='id');
 const infoIdx=r.columns.findIndex(c=>c.toLowerCase()==='info');
 // SHOW FULL PROCESSLIST always includes ITSELF (the instant it runs, it IS a running process) -
 // as a fresh connection each refresh, so it's a different, ever-climbing id every time, is
 // always caught in its own brief "starting" state, and can never actually be killed (it's
 // already finished and disconnected by the time a Kill reaches the server). None of that is
 // useful information, so filter that one row out rather than confuse people with it.
 const showHidden=$('plShowHidden')&&$('plShowHidden').checked;
 const filteredRows=(infoIdx>=0&&!showHidden)?r.rows.filter(row=>{const info=String(row[infoIdx]||'').trim().toLowerCase();return info!=='show full processlist'&&info!=='show processlist';}):r.rows;
 const hiddenCount=r.rows.length-filteredRows.length;
 r.rows=filteredRows;
 $('plStatus').textContent=r.rows.length+' process(es)'+(hiddenCount?' (hid '+hiddenCount+' - this connection\'s own SHOW PROCESSLIST)':'')+'.';
 let h='<table style="width:100%;border-collapse:collapse;font-size:12px"><thead><tr>';
 r.columns.forEach((c,ci)=>{const wide=(ci===idIdx)?'min-width:70px;':'';h+='<th style="text-align:left;padding:4px 6px;border-bottom:1px solid var(--bd2);position:sticky;top:0;background:var(--panel2);'+wide+'">'+esc(c)+'</th>';});
 h+='<th style="padding:4px 6px;border-bottom:1px solid var(--bd2);position:sticky;top:0;background:var(--panel2);width:1%"></th></tr></thead><tbody>';
 r.rows.forEach(row=>{
  h+='<tr>';
  row.forEach(v=>{h+='<td style="padding:4px 6px;border-bottom:1px solid var(--bd2)">'+cellHtml(v)+'</td>';});
  const pid=idIdx>=0?row[idIdx]:null;
  // Same reasoning as the filtering above: this connection's own SHOW [FULL] PROCESSLIST row
  // can never actually be killed, so - when "Show hidden" reveals it anyway - it gets no Kill
  // button at all rather than one that would only ever fail.
  const info=infoIdx>=0?String(row[infoIdx]||'').trim().toLowerCase():'';
  const isSelf=(info==='show full processlist'||info==='show processlist');
  h+='<td style="padding:4px 6px;border-bottom:1px solid var(--bd2)">'+((pid!=null&&!isSelf)?'<button class="sm warn" onclick="killProcess(\''+esc(pid).replace(/\\/g,'\\\\').replace(/\x27/g,'\\x27').replace(/\n/g,'\\n').replace(/\r/g,'\\r')+'\')">Kill</button>':'')+'</td>';
  h+='</tr>';
 });
 h+='</tbody></table>';
 $('plGrid').innerHTML=h;
}
async function killProcess(pid){
 if(!(await ask('Kill process '+pid+'? This immediately terminates its current query/connection.')))return;
 const r=await api('/api/kill-process',{pid});
 if(r.ok){log('Killed process '+pid+'.');refreshProcessList();}
 else{toast(r.error||('Could not kill process '+pid+'.'),true);}
}
// Common privilege combos, similar to what Workbench's own privilege list offers - not exhaustive
// (there's dozens of individual MySQL privileges), just the handful actually reached for often. The
// free-text field underneath stays the source of truth: picking a preset/schema/table just (re)writes
// it for you, and it's still hand-editable for anything these pickers don't cover.
const GRANT_PRESETS=[
 {value:'__custom__',label:'Custom (type below)'},
 {value:'ALL PRIVILEGES',label:'ALL PRIVILEGES'},
 {value:'SELECT',label:'SELECT (read-only)'},
 {value:'SELECT, INSERT, UPDATE, DELETE',label:'SELECT, INSERT, UPDATE, DELETE'},
 {value:'SELECT, INSERT, UPDATE, DELETE, CREATE, ALTER, DROP, INDEX, REFERENCES',label:'SELECT, INSERT, UPDATE, DELETE, CREATE, ALTER, DROP, INDEX, REFERENCES'},
 {value:'EXECUTE',label:'EXECUTE (procedures/functions)'},
 {value:'PROCESS, RELOAD',label:'PROCESS, RELOAD'},
 {value:'REPLICATION SLAVE, REPLICATION CLIENT',label:'REPLICATION SLAVE, REPLICATION CLIENT'},
 {value:'USAGE',label:'USAGE (no privileges)'},
];
// Shared by grantUser()/revokeUser() - the dialog itself doesn't know or care which one it's for
// beyond the title/button text; the caller still does the actual GRANT/REVOKE + FLUSH PRIVILEGES.
async function grantRevokeDialog(mode){
 const isGrant=mode==='grant';
 const sr=await api('/api/schemas');const schemas=sr.ok?sr.schemas.map(s=>s.name):[];
 const fields=[
  {key:'preset',label:'Common privileges',type:'select',options:GRANT_PRESETS,value:'__custom__'},
  {key:'schema',label:'Schema',type:'select',options:[{value:'*',label:'* (all databases)'},...schemas.map(s=>({value:s,label:s}))],value:'*'},
  {key:'table',label:'Table',type:'select',options:[{value:'*',label:'* (all tables)'}],value:'*'},
 ];
 if(isGrant)fields.push({key:'wgo',label:'With grant option',type:'checkbox',value:false});
 fields.push({key:'g',label:'Privileges'+(isGrant?' to grant':' to revoke')+' (e.g. ALL PRIVILEGES ON db.*) - editable directly, or built from the pickers above',value:'ALL PRIVILEGES ON *.*'});
 const p=inputBox({title:isGrant?'Grant privileges':'Revoke privileges',okText:isGrant?'Grant':'Revoke',width:'560px',fields});
 const presetSel=$('inp_preset'),schemaSel=$('inp_schema'),tableSel=$('inp_table'),gInput=$('inp_g'),wgoCk=isGrant?$('inp_wgo'):null;
 // WITH GRANT OPTION is a suffix on the whole GRANT statement (after "TO user@host"), not part of
 // the privilege/target list this field holds - grantUser() appends it separately at exec time, in
 // the right place, based on the checkbox state rather than baking it into this text.
 function rebuild(){
  const on=(schemaSel.value==='*'?'*':qid(schemaSel.value))+'.'+(tableSel.value==='*'?'*':qid(tableSel.value));
  const priv=presetSel.value==='__custom__'?(gInput.value.replace(/\s+ON\s+\S+\.\S+.*$/i,'').trim()||'SELECT'):presetSel.value;
  gInput.value=priv+' ON '+on;
 }
 async function refreshTables(){
  if(schemaSel.value==='*'){tableSel.innerHTML='<option value="*">* (all tables)</option>';tableSel.disabled=true;return;}
  tableSel.disabled=false;tableSel.innerHTML='<option value="*">* (all tables)</option>';
  const tr=await api('/api/query',{sql:'SELECT TABLE_NAME FROM information_schema.TABLES WHERE TABLE_SCHEMA='+lit(schemaSel.value)+' ORDER BY TABLE_NAME'});
  if(tr.ok)tr.rows.forEach(r=>{const o=document.createElement('option');o.value=r[0];o.textContent=r[0];tableSel.appendChild(o);});
 }
 presetSel.onchange=rebuild;tableSel.onchange=rebuild;if(wgoCk)wgoCk.onchange=rebuild;
 schemaSel.onchange=async()=>{await refreshTables();rebuild();};
 await refreshTables();
 return await p;
}
async function revokeUser(){const v=window._selUser;if(!v){toast('Select an account first.',true);return;}const[u,h]=v.split('\x01');const res=await grantRevokeDialog('revoke');if(!res||!res.g.trim())return;if(await exec("REVOKE "+res.g.trim()+" FROM "+uRef(window._selAcct),'Revoked')){await exec('FLUSH PRIVILEGES','Flush');showGrants();}}
async function lockUser(lock){const v=window._selUser;if(!v){toast('Select an account first.',true);return;}const[u,h]=v.split('\x01');const verb=lock?'LOCK':'UNLOCK';if(await exec("ALTER USER "+strLit(u)+"@"+strLit(h)+" ACCOUNT "+verb,(lock?'Locked ':'Unlocked ')+u+'@'+h)){await usersReloadKeep();}}
// The IDENTIFIED VIA clause of a MariaDB account with several sign-in methods, each password-based
// one given pw and every other kept as it is; null when the account has only one method.
function mariaAuthChain(createUser,pw){
 const bare=sqlBlankStringsAndComments(createUser),at=bare.search(/\bIDENTIFIED\s+VIA\s/i);if(at<0)return null;
 const start=at+bare.slice(at).match(/^IDENTIFIED\s+VIA\s+/i)[0].length;
 const endRel=bare.slice(start).search(/\s(REQUIRE|WITH|PASSWORD\s+EXPIRE|ACCOUNT|DEFAULT\s+ROLE)\b/i);
 const end=endRel<0?bare.length:start+endRel;
 const parts=[];let from=start,re=/\sOR\s/ig,m;const seg=bare.slice(start,end);
 while((m=re.exec(seg))){parts.push(createUser.slice(from,start+m.index).trim());from=start+m.index+m[0].length;}
 parts.push(createUser.slice(from,end).trim());
 if(parts.length<2)return null;
 const PW=['mysql_native_password','ed25519','parsec','caching_sha2_password'];
 return 'IDENTIFIED VIA '+parts.map(x=>{const pl=(x.match(/^\w+/)||[''])[0].toLowerCase();return PW.includes(pl)?pl+' USING PASSWORD('+strLit(pw)+')':x;}).join(' OR ');}
async function changePassword(){const v=window._selUser;if(!v){toast('Select an account first.',true);return;}const parts=v.split('\x01');const u=parts[0],h=parts[1];
 const res=await inputBox({title:'Change password for '+u+'@'+h,okText:'Change',fields:[{key:'pw',label:'New password',type:'password',value:''},{key:'pw2',label:'Confirm new password',type:'password',value:''}]});
 if(!res)return;if(!res.pw){toast('Password cannot be empty.',true);return;}if(res.pw!==res.pw2){toast('Passwords do not match.',true);return;}
 // lit() for user/host (matching lockUser()), but strLit() - always quoted - for the password:
 // lit()'s hex-literal passthrough is meant for cell values, not a password field, and a plain
 // quote-double (no backslash escaping first) let a value ending in a backslash close the literal
 // one character early.
 // MariaDB's IDENTIFIED BY switches an ed25519 account to its default plugin; its plugin is named.
 const sa=window._selAcct,keep=window.mariadb&&sa&&['ed25519','parsec'].includes(sa.plugin)?sa.plugin:'';
 let ident=identifiedBy(keep,res.pw);
 // A MariaDB account can sign in more than one way - root@localhost on Linux is usually
 // "unix_socket OR mysql_native_password". IDENTIFIED BY replaces them all with the password
 // (measured: the other method was gone afterwards), so such an account keeps its chain and only
 // the password-based methods in it get the new password.
 if(window.mariadb){const cu=await api('/api/query',{sql:'SHOW CREATE USER '+strLit(u)+'@'+strLit(h)});
  const chain=cu.ok&&cu.rows.length?mariaAuthChain(String(cu.rows[0][0]),res.pw):null;if(chain)ident=chain;}
 const sql="ALTER USER "+strLit(u)+"@"+strLit(h)+" "+ident+";";
 const r=await api('/api/exec',{sql:sql});
 if(r.ok){log('Password changed for '+u+'@'+h+'.');toast('Password changed for '+u+'@'+h+'.','ok');}else{toast('Failed: '+(r.error||'unknown'),true);}}
async function dropUser(){const a=window._selAcct;if(!a)return;const what=a.role?'DROP ROLE':'DROP USER';if(!(await ask(what+' '+uName(a)+' ?')))return;if(await exec(what+' '+uRef(a),a.role?'Dropped role':'Dropped user'))openUsers();}
async function grantUser(){const v=window._selUser;if(!v){toast('Select an account first.',true);return;}const[u,h]=v.split('\x01');const res=await grantRevokeDialog('grant');if(!res||!res.g.trim())return;
 const sql="GRANT "+res.g.trim()+" TO "+uRef(window._selAcct)+(res.wgo?' WITH GRANT OPTION':'');
 if(await exec(sql,'Granted')){await exec('FLUSH PRIVILEGES','Flush');showGrants();}}

// ---- users: the list, an account's details, and what can be done to one ----
// Accounts and roles, each read with what the server knows about it: how it signs in, whether it
// must use SSL, its limits, whether it is locked or its password has expired, and its roles. A
// column a server does not have comes back empty rather than failing the list - mysql.user is not
// the same on MySQL and MariaDB, nor across their versions.
let _uaccts=[],_uRoleSupport=false;
const SYSTEM_ACCTS=['mysql.sys','mysql.session','mysql.infoschema','mariadb.sys'];
function uKey(u,h){return u+'\x01'+h;}
// How a statement names the account: 'user'@'host', or a MariaDB role by its name alone.
function uRef(a){return a.role&&window.mariadb?qid(a.u):strLit(a.u)+'@'+strLit(a.h);}
function uName(a){return a.role&&window.mariadb?a.u:a.u+'@'+a.h;}
async function usersLoad(){
 const cr=await api('/api/query',{sql:"SELECT LOWER(COLUMN_NAME) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='mysql' AND TABLE_NAME='user'"});
 const have=new Set((cr.ok?cr.rows:[]).map(r=>String(r[0])));
 const col=(c,a)=>(have.has(c)?c:'NULL')+' AS '+a;
 const r=await api('/api/query',{sql:'SELECT User,Host,'+[col('plugin','plugin'),col('account_locked','locked'),col('password_expired','expired'),col('password_lifetime','lifetime'),col('ssl_type','ssltype'),col('max_questions','mq'),col('max_updates','mu'),col('max_connections','mc'),col('max_user_connections','muc'),col('is_role','isrole'),col('default_role','defrole')].join(',')+
  (have.has('authentication_string')?",authentication_string='' AS nopw":',NULL AS nopw')+' FROM mysql.user ORDER BY User,Host'});
 if(!r.ok){toast(r.error,true);return false;}
 const acc=r.rows.map(x=>({u:x[0],h:x[1],plugin:x[2]||'',locked:x[3]==='Y',expired:x[4]==='Y',lifetime:x[5]==null?null:+x[5],ssl:x[6]||'',mq:+x[7]||0,mu:+x[8]||0,mc:+x[9]||0,muc:+x[10]||0,
  role:x[11]==='Y',defrole:x[12]||'',nopw:String(x[13])==='1',roles:[],defaults:[]}));
 const byKey=new Map(acc.map(a=>[uKey(a.u,a.h),a]));
 _uRoleSupport=false;
 if(window.mariadb){
  // MariaDB: roles are rows marked is_role, granted through mysql.roles_mapping, with the default
  // role a column of the account.
  // Its lock and its password lifetime are not columns of mysql.user there (10.4 on) but keys
  // of mysql.global_priv's JSON: account_locked, and password_lifetime - absent for the server's
  // default, 0 for never.
  const gp=await api('/api/query',{sql:"SELECT User,Host,JSON_VALUE(Priv,'$.account_locked'),JSON_VALUE(Priv,'$.password_lifetime') FROM mysql.global_priv"});
  if(gp.ok)gp.rows.forEach(([u,h,l,lt])=>{const a=byKey.get(uKey(u,h));if(a){a.locked=l==='true'||l==='1';a.lifetime=lt==null||lt===''?null:+lt;}});
  const m=await api('/api/query',{sql:'SELECT User,Host,Role FROM mysql.roles_mapping'});
  if(m.ok){_uRoleSupport=true;const roles=new Map(acc.filter(a=>a.role).map(a=>[a.u,a]));
   m.rows.forEach(([u,h,role])=>{const a=byKey.get(uKey(u,h))||(h===''?roles.get(u):null),ro=roles.get(role);if(a&&ro&&a!==ro&&!a.roles.includes(ro))a.roles.push(ro);});
   acc.forEach(a=>{const ro=a.defrole&&roles.get(a.defrole);if(ro)a.defaults=[ro];});}
 }else{
  // MySQL 8: a role is an account; the ones granted or set as a default are roles for certain, and
  // one made with CREATE ROLE and not given to anyone yet is a locked account with no password.
  const e=await api('/api/query',{sql:'SELECT FROM_USER,FROM_HOST,TO_USER,TO_HOST FROM mysql.role_edges'});
  if(e.ok){_uRoleSupport=true;const isRole=new Set();
   e.rows.forEach(([fu,fh,tu,th])=>{isRole.add(uKey(fu,fh));const a=byKey.get(uKey(tu,th)),ro=byKey.get(uKey(fu,fh));if(a&&ro&&!a.roles.includes(ro))a.roles.push(ro);});
   const d=await api('/api/query',{sql:'SELECT USER,HOST,DEFAULT_ROLE_USER,DEFAULT_ROLE_HOST FROM mysql.default_roles'});
   if(d.ok)d.rows.forEach(([u,h,ru,rh])=>{isRole.add(uKey(ru,rh));const a=byKey.get(uKey(u,h)),ro=byKey.get(uKey(ru,rh));if(a&&ro)a.defaults.push(ro);});
   acc.forEach(a=>{if(isRole.has(uKey(a.u,a.h))||(a.locked&&a.nopw&&!SYSTEM_ACCTS.includes(a.u)))a.role=true;});}
 }
 _uaccts=acc;return true;}
async function openUsers(){if(!(await usersLoad()))return;$('userFilter').value='';window._selUser='';window._selAcct=null;usersRender();usersPanel();show('mUsers');}
function usersNewMenu(e){e.stopPropagation();const b=e.currentTarget.getBoundingClientRect();const a=window._selAcct;
 menu(b.left,b.bottom+2,[['Create user...',()=>newUser()],_uRoleSupport&&['Create role...',()=>roleCreate()],a&&!a.role&&'-',a&&!a.role&&['Clone '+uName(a)+'...',()=>acctClone()]]);}
// The list: roles, then accounts, each under its heading with what is unusual about it beside its
// name. A click shows it on the right; a double click opens what is edited most - an account's
// settings, a role's privileges.
function usersRender(){const box=$('userSel'),q=($('userFilter').value||'').trim().toLowerCase(),top=box.scrollTop;box.innerHTML='';
 const list=_uaccts.filter(a=>!q||uName(a).toLowerCase().includes(q));
 [['Roles',list.filter(a=>a.role)],['Accounts',list.filter(a=>!a.role)]].forEach(([title,items])=>{if(!items.length)return;
  const g=document.createElement('div');g.className='ugroup';g.textContent=title+' ('+items.length+')';box.appendChild(g);
  items.forEach(a=>{const d=document.createElement('div');d.className='uitem'+(window._selAcct===a?' sel':'');d.title=uName(a);
   const n=document.createElement('span');n.textContent=a.u;
   if(!(a.role&&window.mariadb)){const h=document.createElement('span');h.className='uhost';h.textContent='@'+a.h;n.appendChild(h);}
   d.appendChild(n);
   const tags=[];if(SYSTEM_ACCTS.includes(a.u))tags.push(['system','']);if(a.locked&&!a.role)tags.push(['locked','uwarn']);if(a.expired&&!a.role)tags.push(['expired','uwarn']);
   tags.forEach(([t,c])=>{const s=document.createElement('span');s.className='utag '+c;s.textContent=t;d.appendChild(s);});
   d.onclick=()=>usersPick(a);d.ondblclick=()=>a.role?privOpen():acctEdit();box.appendChild(d);});});
 if(!list.length)box.innerHTML='<div class="muted" style="padding:10px 14px">Nothing matches.</div>';
 box.scrollTop=top;}
function usersPick(a){window._selAcct=a;window._selUser=uKey(a.u,a.h);$('userSel').querySelectorAll('.uitem').forEach(d=>d.classList.toggle('sel',d.title===uName(a)));showGrants();}
const SSL_SAYS={ANY:'SSL required',X509:'SSL with a client certificate required',SPECIFIED:'a specific client certificate required'};
// The right side, for the picked account or role - or a note saying what to do when there is none.
function usersPanel(){const a=window._selAcct;$('uEmpty').style.display=a?'none':'';$('uBody').style.display=a?'':'none';if(!a)return;
 const sys=SYSTEM_ACCTS.includes(a.u);
 $('uTitle').innerHTML=esc(a.u)+(a.role&&window.mariadb?'':'<span class="uhost">@'+esc(a.h)+'</span>');
 const kind=[a.role?'<span class="utag urole">role</span> Its privileges go to the accounts it is given to.':'<span class="utag">account</span>'+(a.h==='%'?' Signs in from anywhere.':a.h==='localhost'?' Signs in from this server only.':' Signs in from '+esc(a.h)+'.')];
 if(sys)kind.push('<span class="utag">system</span> The server\'s own - best left as it is.');
 $('uKind').innerHTML=kind.join(' ');
 const ren=$('uRenameBtn');ren.disabled=!!(a.role&&window.mariadb);ren.title=ren.disabled?'MariaDB cannot rename a role - create one with the new name and give it instead':'Change the name or the host it signs in from - its privileges and roles go with it';
 $('uCloneBtn').style.display=a.role?'none':'';
 $('uDropBtn').title=a.role?'Drop this role - the accounts that have it lose its privileges':'Drop this account';
 $('uAcctSec').style.display=a.role?'none':'';
 if(!a.role){$('userInfo').innerHTML=acctInfoHtml(a);const lb=$('uLockBtn');lb.style.display=acctHasLock()?'':'none';lb.textContent=a.locked?'Unlock':'Lock';
  lb.title=a.locked?'Let it sign in again':'Stop it signing in - it keeps its privileges';}
 $('uRolesH').textContent=a.role?'Given to':'Roles';$('uRolesBtn').style.display=a.role||!_uRoleSupport?'none':'';
 $('uRoles').innerHTML=rolesHtml(a);
 $('uPrivs').innerHTML='<div class="unone">Reading its privileges...</div>';$('grantsBox').textContent='';}
function acctInfoHtml(a){const rows=[];
 rows.push(['Sign-in method',esc(a.plugin||'server default')]);
 rows.push(['Password',a.expired?'<span class="uwarn">expired - to be changed at the next sign-in</span>':a.nopw?'none':'set']);
 if(acctHasExpiry())rows.push(['Password expiry',a.lifetime==null?'server default':a.lifetime===0?'never expires':'every '+a.lifetime+' days']);
 rows.push(['Connection security',SSL_SAYS[a.ssl]||'SSL not required']);
 const lim=[['queries an hour',a.mq],['updates an hour',a.mu],['connections an hour',a.mc],['connections at once',a.muc]].filter(x=>x[1]>0).map(x=>x[1]+' '+x[0]);
 rows.push(['Limits',lim.length?'at most '+lim.join(', '):'none']);
 if(acctHasLock())rows.push(['Status',a.locked?'<span class="uwarn">locked - cannot sign in</span>':'<span class="uok">&#9679;</span> can sign in']);
 return rows.map(([k,v])=>'<div>'+k+'</div><div>'+v+'</div>').join('');}
function rolesHtml(a){if(!_uRoleSupport)return '<div class="unone">This server has no roles - they came with MySQL 8.0 and MariaDB 10.0.5.</div>';
 const chip=(r,tag)=>'<span class="uchip">'+esc(uName(r))+(tag?'<span class="utag urole">'+tag+'</span>':'')+'</span>';
 if(a.role){const to=_uaccts.filter(x=>x.roles.includes(a));return to.length?'<div>'+to.map(x=>chip(x,x.defaults.includes(a)?'default':'')).join('')+'</div>':'<div class="unone">No account has it yet - give it from an account\'s Roles.</div>';}
 return a.roles.length?'<div>'+a.roles.map(r=>chip(r,a.defaults.includes(r)?'default':'')).join('')+'</div>':'<div class="unone">None.</div>';}
// SHOW GRANTS, read into where each privilege applies: one row for each place, with the privileges
// there and whether they may be passed on. A role given to the account ("GRANT r TO ...") is left
// to Roles, and USAGE - no privilege at all - is left out.
function grantRows(lines){const rows=new Map();
 for(const line of lines){const s=String(line);if(!/^GRANT\s/i.test(s))continue;
  let q='',d=0,on=-1;
  for(let i=6;i<s.length;i++){const c=s[i];
   if(q){if(c===q){if(s[i+1]===q)i++;else q='';}continue;}
   if(c==='`'||c==="'"||c==='"'){q=c;continue;}
   if(c==='(')d++;else if(c===')')d--;else if(d===0&&/\s/.test(c)&&/^\sON\s/i.test(s.slice(i,i+4))){on=i;break;}}
  if(on<0)continue;
  const privs=[];let cur='';q='';d=0;
  for(const c of s.slice(6,on)){if(q){cur+=c;if(c===q)q='';continue;}if(c==='`'||c==="'"){q=c;cur+=c;continue;}
   if(c==='(')d++;else if(c===')')d--;if(c===','&&d===0){privs.push(cur.trim());cur='';}else cur+=c;}
  if(cur.trim())privs.push(cur.trim());
  let rest=s.slice(on+4).trimStart(),kind='';
  const km=rest.match(/^(PROCEDURE|FUNCTION|TABLE)\s+/i);if(km){kind=km[1].toUpperCase();rest=rest.slice(km[0].length);}
  const parts=[];let i=0;
  while(i<rest.length){
   if(rest[i]==='`'){let j=i+1,n='';while(j<rest.length){if(rest[j]==='`'){if(rest[j+1]==='`'){n+='`';j+=2;continue;}break;}n+=rest[j++];}parts.push(n);i=j+1;}
   else{const m=rest.slice(i).match(/^[^\s.]+/);if(!m)break;parts.push(m[0]);i+=m[0].length;}
   if(rest[i]==='.'){i++;continue;}break;}
  const tail=rest.slice(i).replace(/'(?:[^'\\]|\\.|'')*'/g,"''").replace(/`(?:[^`]|``)*`/g,'``');
  const wgo=/\bWITH\s+GRANT\s+OPTION\b/i.test(tail);
  const p=privs.filter(x=>!/^USAGE$/i.test(x));if(!p.length)continue;
  const key=kind+'\x01'+parts.join('\x01')+'\x01'+wgo;
  if(!rows.has(key))rows.set(key,{kind,parts,privs:[],wgo});
  const r=rows.get(key);p.forEach(x=>{if(!r.privs.includes(x))r.privs.push(x);});}
 return [...rows.values()];}
// Where a row applies, as [what, name, is a pattern, sort order]. In a database grant _ and % match
// any character, so a name holding one unescaped covers every database whose name fits.
function grantPlace(r){const P=r.parts,un=n=>n.replace(/\\([_%\\])/g,'$1');
 if(r.privs.length===1&&/^PROXY$/i.test(r.privs[0]))return ['Proxy for',P.join('.'),false,4];
 if(P.length===2&&P[0]==='*'&&P[1]==='*')return ['Server','every database',false,0];
 if(P.length===2&&P[1]==='*')return ['Database',un(P[0]),/(^|[^\\])[_%]/.test(P[0]),1];
 if(r.kind==='PROCEDURE'||r.kind==='FUNCTION')return [r.kind==='PROCEDURE'?'Procedure':'Function',P.join('.'),false,3];
 return [r.privs.some(x=>/\(/.test(x))?'Columns of table':'Table',P.join('.'),false,2];}
const UPRIV_SHOWN=12;
function privRowsHtml(a,lines){const rows=grantRows(lines).map(r=>({r,pl:grantPlace(r)})).sort((x,y)=>x.pl[3]-y.pl[3]||x.pl[1].localeCompare(y.pl[1]));
 const fromRoles=!a.role&&a.roles.length?'<div class="unote">Privileges that come with its roles are not listed here - they are the roles\' own.</div>':'';
 if(!rows.length)return '<div class="unone">'+(a.role?'No privileges yet.':'No privileges - it can sign in and nothing more.')+'</div>'+fromRoles;
 return '<table class="utab"><colgroup><col class="c1"><col><col class="c3"></colgroup><thead><tr><th>Applies to</th><th>Privileges</th><th>Can grant</th></tr></thead><tbody>'+
  rows.map(({r,pl})=>{const chips=r.privs.map((x,i)=>'<span class="upriv'+(/^ALL( PRIVILEGES)?$/i.test(x)?' uall':'')+(i>=UPRIV_SHOWN?' umore':'')+'">'+esc(x)+'</span>').join('');
   const more=r.privs.length>UPRIV_SHOWN?'<span class="umorebtn" onclick="this.parentNode.classList.add(\'open\')">+'+(r.privs.length-UPRIV_SHOWN)+' more</span>':'';
   return '<tr><td><span class="uplace">'+pl[0]+'</span>'+esc(pl[1])+(pl[2]?' <span class="utag uwarn" title="_ and % in a database grant match any character, so this also covers other databases whose names fit">name pattern</span>':'')+'</td><td class="uprivs">'+chips+more+'</td><td>'+(r.wgo?'yes':'<span class="muted">no</span>')+'</td></tr>';}).join('')+
  '</tbody></table>'+fromRoles;}
async function showGrants(){const a=window._selAcct;usersPanel();if(!a)return;
 const r=await api('/api/query',{sql:'SHOW GRANTS FOR '+uRef(a)});if(window._selAcct!==a)return;
 const lines=r.ok?r.rows.map(x=>String(x[0])):[];
 $('grantsBox').textContent=r.ok?lines.join('\n'):r.error;
 $('uPrivs').innerHTML=r.ok?privRowsHtml(a,lines):'<div class="unone">'+esc(r.error)+'</div>';}
async function usersReloadKeep(){const k=window._selUser;await usersLoad();window._selAcct=_uaccts.find(a=>uKey(a.u,a.h)===k)||null;usersRender();showGrants();}
function usersSelect(u,h){window._selAcct=_uaccts.find(a=>a.u===u&&a.h===h)||null;window._selUser=window._selAcct?uKey(u,h):'';usersRender();showGrants();}
// A new name or host for the account. RENAME USER keeps its privileges, roles and settings; a
// MariaDB role cannot be renamed.
async function acctRename(){const a=window._selAcct;if(!a)return;
 if(a.role&&window.mariadb){toast('MariaDB cannot rename a role - create one with the new name and give it instead.',true);return;}
 const res=await inputBox({title:'Rename '+uName(a),okText:'Rename',width:'460px',fields:[{key:'user',label:a.role?'Role name':'User name',value:a.u},{key:'host',label:'Host - % for anywhere',value:a.h}]});
 if(!res)return;const u=String(res.user||'').trim(),h=String(res.host||'').trim()||'%';
 if(!u){toast('The name cannot be empty.',true);return;}if(u===a.u&&h===a.h){toast('Nothing to change.');return;}
 const sql='RENAME USER '+uRef(a)+' TO '+strLit(u)+'@'+strLit(h)+';';
 const r=await api('/api/script',{sql});if(!r.ok){toast(r.error,true);return;}
 log(sql);toast('Renamed to '+u+'@'+h+'.','ok');await usersLoad();usersSelect(u,h);}

// ---- privileges as a checklist ----
// The privileges at one level - the whole server, a database, a table - as boxes, ticked for what
// the account has. What changes is shown as the GRANT and REVOKE it becomes before it is applied.
// Which privileges a level offers is the server's own list (SHOW PRIVILEGES), so a MySQL-only or
// MariaDB-only privilege appears where it exists and nowhere else.
const PRIV_TABLE=['SELECT','INSERT','UPDATE','DELETE','CREATE','DROP','ALTER','INDEX','REFERENCES','CREATE VIEW','SHOW VIEW','TRIGGER','DELETE HISTORY'];
// SHOW CREATE ROUTINE is MariaDB 11.3's; like every entry it is shown only where SHOW PRIVILEGES lists it.
const PRIV_DB=[...PRIV_TABLE,'CREATE TEMPORARY TABLES','LOCK TABLES','EXECUTE','CREATE ROUTINE','ALTER ROUTINE','EVENT','SHOW CREATE ROUTINE'];
let _priv={acct:null,known:[],had:new Set(),hadGO:false};
async function privOpen(){const a=window._selAcct;if(!a){toast('Select an account or a role first.',true);return;}
 _priv.acct=a;_priv.wild=null;const sp=await api('/api/query',{sql:'SHOW PRIVILEGES'});
 _priv.known=(sp.ok&&sp.rows.length?sp.rows.map(r=>String(r[0]).toUpperCase()):PRIV_DB).filter(p=>!['USAGE','PROXY','GRANT OPTION'].includes(p));
 const sr=await api('/api/schemas');$('privDb').innerHTML=(sr.ok?sr.schemas:[]).map(s=>'<option>'+esc(s.name)+'</option>').join('');
 if(curSchema)$('privDb').value=curSchema;
 $('privTitle').textContent='Privileges of '+uName(a);show('mPriv');await privScopeChanged();}
async function privScopeChanged(){const sc=$('privScope').value;$('privDb').style.display=sc==='global'?'none':'';$('privTable').style.display=sc==='table'?'':'none';
 if(sc==='table'){const tr=await api('/api/query',{sql:'SELECT TABLE_NAME FROM information_schema.TABLES WHERE TABLE_SCHEMA='+lit($('privDb').value)+' ORDER BY TABLE_NAME'});
  $('privTable').innerHTML=(tr.ok?tr.rows:[]).map(r=>'<option>'+esc(r[0])+'</option>').join('');}
 await privLoad();}
function privTarget(){const sc=$('privScope').value;return sc==='global'?'*.*':sc==='db'?qid(_priv.dbForm||$('privDb').value)+'.*':qid($('privDb').value)+'.'+qid($('privTable').value);}
// In a database-level grant "_" and "%" are wildcards - on MariaDB, and on MySQL unless
// partial_revokes is on - so SELECT granted on my_app was also SELECT on myXapp and my1app. A grant
// made here names the database exactly (my\_app). One that already exists in the wildcard form
// is kept in that form, so that taking a privilege away revokes what is really there, and the
// window says what it covers.
function privDbEscape(n){return String(n).replace(/[\\_%]/g,'\\$&');}
async function privWildcards(){if(_priv.wild!=null)return _priv.wild;let wild=true;
 if(!window.mariadb){try{const r=await api('/api/query',{sql:'SELECT @@partial_revokes'});if(r&&r.ok&&r.rows.length)wild=!(+r.rows[0][0]);}catch(e){}}
 return _priv.wild=wild;}
// information_schema names a grantee 'user'@'host', and a MariaDB role 'role' alone.
function privGrantees(a){const u=String(a.u).replace(/'/g,"''"),h=String(a.h).replace(/'/g,"''");return ["'"+u+"'@'"+h+"'","'"+u+"'"].map(strLit).join(',');}
async function privLoad(){const a=_priv.acct,sc=$('privScope').value;if(!a)return;const g=privGrantees(a);
 if(sc==='table'&&!$('privTable').value){$('privList').innerHTML='<div class="muted">This database has no tables.</div>';_priv.had=new Set();_priv.hadGO=false;privPreview();return;}
 _priv.dbForm=null;let wildNote='';
 const raw=$('privDb').value,exact=privDbEscape(raw),dbWild=sc==='db'&&exact!==raw&&await privWildcards();
 const where=sc==='global'?'':' AND TABLE_SCHEMA'+(dbWild?' IN ('+lit(raw)+','+lit(exact)+')':'='+lit(raw))+(sc==='table'?' AND TABLE_NAME='+lit($('privTable').value):'');
 const t=sc==='global'?'USER_PRIVILEGES':sc==='db'?'SCHEMA_PRIVILEGES':'TABLE_PRIVILEGES';
 const r0=await api('/api/query',{sql:'SELECT PRIVILEGE_TYPE,IS_GRANTABLE'+(dbWild?',TABLE_SCHEMA':'')+' FROM information_schema.'+t+' WHERE GRANTEE IN ('+g+')'+where});let rows=r0.ok?r0.rows:[];
 if(dbWild){const wildRows=rows.filter(x=>x[2]===raw);_priv.dbForm=wildRows.length?raw:exact;rows=wildRows.length?wildRows:rows.filter(x=>x[2]===exact);
  if(wildRows.length)wildNote='<div class="muted" style="margin-top:8px;font-size:12px;color:var(--warn,#b8860b)">These were granted on '+esc(raw)+' as a pattern: "_" and "%" match any character, so they also apply to every database whose name fits it. Changes here are made to that same grant.</div>';}
 _priv.had=new Set(rows.map(x=>String(x[0]).toUpperCase()).filter(p=>p!=='USAGE'));_priv.hadGO=rows.some(x=>x[1]==='YES');
 const allowed=sc==='global'?_priv.known:(sc==='db'?PRIV_DB:PRIV_TABLE).filter(p=>_priv.known.includes(p));
 const data=allowed.filter(p=>PRIV_DB.includes(p)),admin=allowed.filter(p=>!PRIV_DB.includes(p));
 const box=p=>'<label class="ck"><input type="checkbox" value="'+esc(p)+'"'+(_priv.had.has(p)?' checked':'')+' onchange="privPreview()"> '+esc(p)+'</label>';
 $('privList').innerHTML=(sc==='global'?'<div class="psec">Data and structure, in every database</div>':'')+'<div class="pgrid">'+data.map(box).join('')+'</div>'+
  (admin.length?'<div class="psec">Running the server</div><div class="pgrid">'+admin.map(box).join('')+'</div>':'')+
  (sc!=='global'?'<div class="muted" style="margin-top:8px;font-size:12px">Privileges on single columns or routines are not shown here - use Type a GRANT for those.</div>':'')+wildNote;
 $('privGO').checked=_priv.hadGO;privPreview();}
// The statements the boxes stand for: a GRANT for what was added, a REVOKE for what was taken away.
function privSqlFor(){const a=_priv.acct;if(!a)return [];const on=privTarget(),who=uRef(a);
 const shown=new Set([...$('privList').querySelectorAll('input[type=checkbox]')].map(b=>b.value));
 const want=new Set([...$('privList').querySelectorAll('input:checked')].map(b=>b.value));
 const add=[...want].filter(p=>!_priv.had.has(p)),del=[..._priv.had].filter(p=>shown.has(p)&&!want.has(p));
 const go=$('privGO').checked,out=[];
 // WITH GRANT OPTION belongs to the level, not to a privilege: given once, it covers them all.
 if(add.length||(go&&!_priv.hadGO&&want.size))out.push('GRANT '+(add.length?add:[...want]).join(', ')+' ON '+on+' TO '+who+(go?' WITH GRANT OPTION':'')+';');
 if(del.length)out.push('REVOKE '+del.join(', ')+' ON '+on+' FROM '+who+';');
 if(!go&&_priv.hadGO)out.push('REVOKE GRANT OPTION ON '+on+' FROM '+who+';');
 return out;}
function privPreview(){const s=privSqlFor();$('privSql').textContent=s.length?s.join('\n'):'-- Nothing to change.';$('privApply').disabled=!s.length;}
async function privApply(){const s=privSqlFor();if(!s.length)return;const r=await api('/api/script',{sql:s.join('\n')});
 if(!r.ok){toast(r.error,true);return;}log(s.join('\n'));toast('Privileges changed.','ok');await privLoad();await usersReloadKeep();}

// ---- roles ----
async function roleCreate(){if(!_uRoleSupport){toast('This server has no roles - they came with MySQL 8.0 and MariaDB 10.0.5.',true);return;}
 const res=await inputBox({title:'Create role',okText:'Create',fields:[{key:'n',label:'Role name'}]});if(!res||!res.n.trim())return;const n=res.n.trim();
 if(await exec('CREATE ROLE '+(window.mariadb?qid(n):strLit(n)+'@'+strLit('%')),'Created role '+n)){await usersLoad();usersSelect(n,window.mariadb?'':'%');}}
// Which roles an account has, and which one is active when it signs in.
async function rolesEdit(){const a=window._selAcct;if(!a){toast('Select an account first.',true);return;}
 if(!_uRoleSupport){toast('This server has no roles - they came with MySQL 8.0 and MariaDB 10.0.5.',true);return;}
 const roles=_uaccts.filter(r=>r.role&&r!==a);if(!roles.length){toast('There are no roles yet - make one with Create role.',true);return;}
 const cur=a.defaults.length>1?'__all__':a.defaults.length?String(roles.indexOf(a.defaults[0])):'';
 const fields=roles.map((r,i)=>({key:'r'+i,label:uName(r),type:'checkbox',value:a.roles.includes(r),
  title:'Give '+uName(r)+' to '+uName(a)+'. Its privileges count while the role is active: the default role is active from sign-in, the others after SET ROLE.'}));
 fields.push({key:'def',label:'Default role - the one active when '+uName(a)+' signs in',title:'The role whose privileges '+uName(a)+' has from the moment it signs in. A role that is not the default has to be switched on with SET ROLE first.',type:'select',
  options:[{value:'',label:'None'},...(window.mariadb?[]:[{value:'__all__',label:'All the roles it has'}]),...roles.map((r,i)=>({value:String(i),label:uName(r)}))],value:cur});
 const res=await inputBox({title:'Roles of '+uName(a),okText:'Apply',fields});if(!res)return;
 const who=uRef(a),out=[];
 roles.forEach((r,i)=>{const has=a.roles.includes(r),want=!!res['r'+i];if(want&&!has)out.push('GRANT '+uRef(r)+' TO '+who+';');if(!want&&has)out.push('REVOKE '+uRef(r)+' FROM '+who+';');});
 const d=res.def,defRole=d&&d!=='__all__'?roles[+d]:null;
 if(defRole&&!res['r'+d]){toast('The default role has to be one of the roles the account has.',true);return;}
 if(d!==cur)out.push(window.mariadb?'SET DEFAULT ROLE '+(defRole?uRef(defRole):'NONE')+' FOR '+who+';':'SET DEFAULT ROLE '+(d==='__all__'?'ALL':defRole?uRef(defRole):'NONE')+' TO '+who+';');
 if(!out.length)return;const r=await api('/api/script',{sql:out.join('\n')});if(!r.ok){toast(r.error,true);return;}
 log(out.join('\n'));toast('Roles changed.','ok');await usersReloadKeep();}

// ---- account settings ----
// The sign-in methods this server has switched on and a password can be given for.
async function authPlugins(){const r=await api('/api/query',{sql:"SELECT PLUGIN_NAME FROM information_schema.PLUGINS WHERE PLUGIN_TYPE='AUTHENTICATION' AND PLUGIN_STATUS='ACTIVE' ORDER BY PLUGIN_NAME"});
 return (r.ok?r.rows.map(x=>x[0]):[]).filter(p=>['mysql_native_password','caching_sha2_password','sha256_password','ed25519','parsec'].includes(p));}
// The IDENTIFIED clause for a password: MariaDB names a plugin with VIA ... USING PASSWORD(), MySQL
// with WITH ... BY. No plugin means the server's default.
function identifiedBy(plugin,pw){if(!plugin)return 'IDENTIFIED BY '+strLit(pw);
 return window.mariadb?'IDENTIFIED VIA '+plugin+' USING PASSWORD('+strLit(pw)+')':'IDENTIFIED WITH '+plugin+' BY '+strLit(pw);}
// Whether the connected server is at least this version - MySQL's number or MariaDB's. A version
// that cannot be read counts as new enough, so nothing is taken away on a guess.
function srvSince(my,ma){const m=String(window.serverVersion||'').match(/^(\d+)\.(\d+)\.(\d+)/);if(!m)return true;
 const n=m.slice(1).map(Number),w=window.mariadb?ma:my;for(let i=0;i<3;i++)if(n[i]!==w[i])return n[i]>w[i];return true;}
// Password expiry per account came with MySQL 5.7.4 and MariaDB 10.4.3, locking with 5.7.6 and 10.4.2.
// Offered on an older server, Create user made the account and then failed on the next statement.
function acctHasExpiry(){return srvSince([5,7,4],[10,4,3]);}
function acctHasLock(){return srvSince([5,7,6],[10,4,2]);}
function acctExpiry(a){return !a||a.lifetime==null?'default':a.lifetime===0?'never':'days';}
function acctSettingFields(a,group){return [
 // An account that requires a particular certificate (ISSUER, SUBJECT or CIPHER) keeps that as its
 // own choice; it used to show as "SSL not required", one change away from being written so.
 {key:'ssl',label:'Connection security',type:'select',options:[{value:'NONE',label:'SSL not required'},{value:'ANY',label:'SSL required'},{value:'X509',label:'SSL with a client certificate required'},...(a&&a.ssl==='SPECIFIED'?[{value:'SPECIFIED',label:'A specific client certificate required (kept as it is)'}]:[])],value:a&&['X509','ANY','SPECIFIED'].includes(a.ssl)?a.ssl:'NONE',group},
 ...(acctHasExpiry()?[{key:'exp',label:'Password expiry',type:'select',options:[{value:'default',label:'Server default'},{value:'never',label:'Never expires'},{value:'days',label:'Expires after the days below'}],value:acctExpiry(a),group},
 {key:'days',label:'Days until the password expires',value:a&&a.lifetime>0?String(a.lifetime):'90',group}]:[]),
 {key:'mq',label:'Queries an hour (0 = no limit)',value:String(a?a.mq:0),group},
 {key:'mu',label:'Updates an hour (0 = no limit)',value:String(a?a.mu:0),group},
 {key:'mc',label:'Connections an hour (0 = no limit)',value:String(a?a.mc:0),group},
 {key:'muc',label:'Connections at once (0 = no limit)',value:String(a?a.muc:0),group}];}
// ALTER USER for what differs from a (everything that is not the default, for a new account).
function acctSettingSql(who,res,a){const out=[],n=k=>Math.max(0,parseInt(res[k],10)||0),curSsl=a&&['X509','ANY','SPECIFIED'].includes(a.ssl)?a.ssl:'NONE';
 if(res.ssl!==curSsl&&res.ssl!=='SPECIFIED')out.push('ALTER USER '+who+' REQUIRE '+(res.ssl==='ANY'?'SSL':res.ssl)+';');
 const lim=[['MAX_QUERIES_PER_HOUR','mq'],['MAX_UPDATES_PER_HOUR','mu'],['MAX_CONNECTIONS_PER_HOUR','mc'],['MAX_USER_CONNECTIONS','muc']].filter(([,k])=>n(k)!==(a?a[k]:0));
 if(lim.length)out.push('ALTER USER '+who+' WITH '+lim.map(([s,k])=>s+' '+n(k)).join(' ')+';');
 const days=Math.max(1,n('days'));
 if(acctHasExpiry()&&'exp' in res&&(res.exp!==acctExpiry(a)||(res.exp==='days'&&a&&a.lifetime!==days)))
  out.push('ALTER USER '+who+' '+(res.exp==='never'?'PASSWORD EXPIRE NEVER':res.exp==='days'?'PASSWORD EXPIRE INTERVAL '+days+' DAY':'PASSWORD EXPIRE DEFAULT')+';');
 return out;}
// Statements that carry a password are logged without it.
function logNoSecrets(s){log(sqlNoSecrets(s));}
async function newUser(){const plugins=await authPlugins();
 const res=await inputBox({title:'Create user',okText:'Create',width:'520px',fields:[{key:'user',label:'User name'},{key:'host',label:'Host - % for anywhere',value:'%'},{key:'pw',label:'Password',type:'password'},
  {key:'plugin',label:'Sign-in method',type:'select',options:[{value:'',label:'Server default'},...plugins.map(p=>({value:p,label:p}))],value:''},
  {key:'more',label:'More settings: connection security, '+(acctHasExpiry()?'password expiry, ':'')+'limits',type:'checkbox',value:false,reveals:'more'},...acctSettingFields(null,'more')]});
 if(!res||!res.user.trim())return;const u=res.user.trim(),h=res.host.trim()||'%',who=strLit(u)+'@'+strLit(h);
 const s=['CREATE USER '+who+' '+identifiedBy(res.plugin,res.pw)+';',...(res.more?acctSettingSql(who,res,null):[])];
 const r=await api('/api/script',{sql:s.join('\n')});if(!r.ok){toast(r.error,true);return;}
 logNoSecrets(s.join('\n'));toast('Created '+u+'@'+h+'.','ok');await usersLoad();usersSelect(u,h);}
async function acctEdit(){const a=window._selAcct;if(!a){toast('Select an account first.',true);return;}
 if(a.role){toast('A role does not sign in, so it has no account settings.',true);return;}
 const plugins=await authPlugins();if(a.plugin&&!plugins.includes(a.plugin))plugins.unshift(a.plugin);
 const res=await inputBox({title:'Account settings of '+uName(a),okText:'Apply',width:'520px',fields:[
  {key:'plugin',label:'Sign-in method - to change it, give a password as well',type:'select',options:plugins.map(p=>({value:p,label:p})),value:a.plugin},
  {key:'pw',label:'New password - only to change it, or the sign-in method',type:'password',value:''},
  ...acctSettingFields(a),...(acctHasLock()?[{key:'locked',label:'Locked - cannot sign in',type:'checkbox',value:a.locked}]:[])]});
 if(!res)return;const who=uRef(a),out=acctSettingSql(who,res,a);
 // MariaDB's IDENTIFIED BY switches the account to its default plugin, so the plugin is always named there.
 if(res.pw)out.unshift('ALTER USER '+who+' '+identifiedBy(res.plugin!==a.plugin||window.mariadb?res.plugin:'',res.pw)+';');
 else if(res.plugin!==a.plugin){toast('Changing the sign-in method needs the password as well.',true);return;}
 if('locked' in res&&res.locked!==a.locked)out.push('ALTER USER '+who+' ACCOUNT '+(res.locked?'LOCK':'UNLOCK')+';');
 if(!out.length){toast('Nothing to change.');return;}
 const r=await api('/api/script',{sql:out.join('\n')});if(!r.ok){toast(r.error,true);return;}
 logNoSecrets(out.join('\n'));toast('Account settings changed.','ok');await usersReloadKeep();}

// ---- clone ----
// A new account like the selected one: its sign-in method, settings, grants and roles, with a name,
// host and password of its own. The grants are the source's SHOW GRANTS with the new name put in;
// MariaDB writes the source's password into its GRANT USAGE line, and that part is left out.
// The account is written as MySQL 8 and MariaDB 10.3+ write it, `u`@`h`, or as MySQL 5.7 ('u' with
// \' inside) and MariaDB 10.2 ('u' as it is) do - a clone there used to come out with no grants.
function cloneGrantSql(lines,a,u,h){const bq=s=>'`'+String(s).replace(/`/g,'``')+'`',dst=bq(u)+'@'+bq(h);
 const forms=[bq,s=>"'"+String(s).replace(/\\/g,'\\\\').replace(/'/g,"\\'")+"'",s=>"'"+s+"'"],srcs=forms.map(f=>f(a.u)+'@'+f(a.h));
 return lines.map(s=>{for(const src of srcs)for(const kw of [' TO ',' FOR ']){const i=s.lastIndexOf(kw+src);if(i>=0){const t=s.slice(0,i)+kw+dst+s.slice(i+kw.length+src.length);
   return t.replace(/\s+IDENTIFIED\s+(BY\s+PASSWORD\s+'[^']*'|VIA\s+.*?)(?=\s+(WITH|REQUIRE)\b|$)/i,'')+';';}}return null;}).filter(Boolean);}
// REQUIRE ISSUER/SUBJECT/CIPHER as the account has it. A clone used to get no requirement at all -
// weaker than the account it was made from - since SHOW GRANTS on MySQL 8 does not carry it.
async function acctRequireSpecified(a,who){if(a.ssl!=='SPECIFIED')return [];
 const q=await api('/api/query',{sql:'SELECT CONVERT(x509_issuer USING utf8mb4),CONVERT(x509_subject USING utf8mb4),CONVERT(ssl_cipher USING utf8mb4) FROM mysql.user WHERE User='+lit(a.u)+' AND Host='+lit(a.h)});
 if(!q.ok||!q.rows.length){toast('Could not read the certificate '+uName(a)+' requires, so it was not cloned: '+(q.error||'no row'),true);return null;}
 const [iss,sub,ci]=q.rows[0],parts=[iss&&'ISSUER '+strLit(iss),sub&&'SUBJECT '+strLit(sub),ci&&'CIPHER '+strLit(ci)].filter(Boolean);
 return parts.length?['ALTER USER '+who+' REQUIRE '+parts.join(' AND ')+';']:['ALTER USER '+who+' REQUIRE X509;'];}
async function acctClone(){const a=window._selAcct;if(!a){toast('Select an account first.',true);return;}
 if(a.role){toast('Clone makes accounts - select an account rather than a role.',true);return;}
 const res=await inputBox({title:'Clone '+uName(a),okText:'Clone',fields:[{key:'user',label:'New user name',value:a.u+'_copy'},{key:'host',label:'Host',value:a.h},{key:'pw',label:'Password for the new account',type:'password'}]});
 if(!res||!res.user.trim())return;const u=res.user.trim(),h=res.host.trim()||'%',who=strLit(u)+'@'+strLit(h);
 const g=await api('/api/query',{sql:'SHOW GRANTS FOR '+uRef(a)});if(!g.ok){toast(g.error,true);return;}
 const plugins=await authPlugins(),plugin=plugins.includes(a.plugin)?a.plugin:'';
 const req=await acctRequireSpecified(a,who);if(req===null)return;
 const s=['CREATE USER '+who+' '+identifiedBy(plugin,res.pw)+';',
  ...acctSettingSql(who,{ssl:a.ssl==='X509'?'X509':a.ssl==='ANY'?'ANY':'NONE',exp:acctExpiry(a),days:String(a.lifetime||90),mq:a.mq,mu:a.mu,mc:a.mc,muc:a.muc},null),
  ...req,
  ...cloneGrantSql(g.rows.map(x=>String(x[0])),a,u,h)];
 if(!window.mariadb&&a.defaults.length)s.push('SET DEFAULT ROLE '+a.defaults.map(uRef).join(', ')+' TO '+who+';');
 const r=await api('/api/script',{sql:s.join('\n')});if(!r.ok){toast(r.error,true);return;}
 logNoSecrets(s.join('\n'));toast('Cloned '+uName(a)+' as '+u+'@'+h+'.','ok');await usersLoad();usersSelect(u,h);}

// ---- who has access ----
// Everyone with privileges on a database: on the whole server (its data privileges), on the
// database, on its tables and on their columns - one row for each account, with where each set of
// privileges applies. Privileges that come through a role are listed under the role; a click on an
// account opens it in Users.
async function whoHasAccess(db){const sr=await api('/api/schemas');const schemas=sr.ok?sr.schemas.map(s=>s.name):[];if(!schemas.length)return;
 const sel=$('accDb');sel.innerHTML='';schemas.forEach(n=>{const o=document.createElement('option');o.value=n;o.textContent=n;sel.appendChild(o);});
 sel.value=db&&schemas.includes(db)?db:(schemas.includes(curSchema)?curSchema:schemas[0]);$('accFilter').value='';
 show('mAccess');await accLoad();}
let _acc=null;
async function accLoad(){const db=$('accDb').value,sep=" SEPARATOR ', ')";if(!db)return;
 $('accList').innerHTML='<div class="unone">Reading who has access to '+esc(db)+'...</div>';
 const qs=["SELECT GRANTEE,'server','',GROUP_CONCAT(PRIVILEGE_TYPE ORDER BY PRIVILEGE_TYPE"+sep+" FROM information_schema.USER_PRIVILEGES WHERE PRIVILEGE_TYPE IN ("+PRIV_DB.map(strLit).join(',')+") GROUP BY GRANTEE",
  "SELECT GRANTEE,'database','',GROUP_CONCAT(PRIVILEGE_TYPE ORDER BY PRIVILEGE_TYPE"+sep+" FROM information_schema.SCHEMA_PRIVILEGES WHERE TABLE_SCHEMA IN ("+lit(db)+","+lit(privDbEscape(db))+") GROUP BY GRANTEE",
  "SELECT GRANTEE,'table',TABLE_NAME,GROUP_CONCAT(PRIVILEGE_TYPE ORDER BY PRIVILEGE_TYPE"+sep+" FROM information_schema.TABLE_PRIVILEGES WHERE TABLE_SCHEMA="+lit(db)+" GROUP BY GRANTEE,TABLE_NAME",
  "SELECT GRANTEE,'column',CONCAT(TABLE_NAME,'.',COLUMN_NAME),GROUP_CONCAT(PRIVILEGE_TYPE ORDER BY PRIVILEGE_TYPE"+sep+" FROM information_schema.COLUMN_PRIVILEGES WHERE TABLE_SCHEMA="+lit(db)+" GROUP BY GRANTEE,TABLE_NAME,COLUMN_NAME"];
 const by=new Map();
 for(const q of qs){const r=await api('/api/query',{sql:q});if(r.ok)r.rows.forEach(([g,kind,name,p])=>{if(!by.has(g))by.set(g,[]);by.get(g).push({kind,name:String(name||''),privs:String(p||'').split(', ').filter(Boolean)});});}
 if($('accDb').value!==db)return;
 // 'user'@'host' as the server writes it, and the account behind it if the Users list knows it
 const parse=g=>{const m=String(g).match(/^'((?:[^']|'')*)'(?:@'((?:[^']|'')*)')?$/);return m?{u:m[1].replace(/''/g,"'"),h:m[2]!=null?m[2].replace(/''/g,"'"):null}:{u:String(g),h:null};};
 if(!_uaccts.length){try{await usersLoad();}catch(e){}}
 _acc={db,rows:[...by.entries()].map(([g,places])=>{const a=parse(g),acct=_uaccts.find(x=>x.u===a.u&&(a.h==null||x.h===a.h))||null;
  const order={server:0,database:1,table:2,column:3};places.sort((x,y)=>order[x.kind]-order[y.kind]||x.name.localeCompare(y.name));
  return {u:a.u,h:a.h,name:a.h!=null?a.u+'@'+a.h:a.u,acct,places};}).sort((x,y)=>x.name.localeCompare(y.name))};
 accRender();}
function accRender(){if(!_acc)return;const q=($('accFilter').value||'').trim().toLowerCase(),box=$('accList');
 const rows=_acc.rows.filter(r=>!q||r.name.toLowerCase().includes(q));
 $('accCount').textContent=_acc.rows.length?(rows.length===_acc.rows.length?rows.length+' account'+(rows.length===1?'':'s'):rows.length+' of '+_acc.rows.length):'';
 if(!_acc.rows.length){box.innerHTML='<div class="unone">Nobody has privileges on '+esc(_acc.db)+' of their own - only accounts with privileges on the whole server can use it.</div>';return;}
 if(!rows.length){box.innerHTML='<div class="unone">No account matches.</div>';return;}
 const WHERE={server:'Server',database:'Database',table:'Table',column:'Column'};
 box.innerHTML='<table class="utab"><colgroup><col style="width:30%"><col></colgroup><thead><tr><th>Account</th><th>What it may do, and where</th></tr></thead><tbody>'+rows.map(r=>{
  const tags=(r.acct&&r.acct.role?'<span class="utag urole">role</span>':'')+(r.acct&&SYSTEM_ACCTS.includes(r.acct.u)?'<span class="utag">system</span>':'')+(r.acct&&r.acct.locked&&!r.acct.role?'<span class="utag uwarn">locked</span>':'');
  const who='<a href="#" class="acclink" data-u="'+esc(r.u)+'" data-h="'+esc(r.h==null?'':r.h)+'" title="Open it in Users">'+esc(r.u)+(r.h!=null?'<span class="uhost">@'+esc(r.h)+'</span>':'')+'</a>'+(tags?' '+tags:'');
  const places=r.places.map(p=>'<div class="accplace"><div class="accwhere"><span class="accw">'+WHERE[p.kind]+'</span>'+(p.name?'<span class="accn">'+esc(p.name)+'</span>':'')+'</div><div>'+p.privs.map(x=>'<span class="upriv'+(/^ALL( PRIVILEGES)?$/i.test(x)?' uall':'')+'">'+esc(x)+'</span>').join('')+'</div></div>').join('');
  return '<tr><td>'+who+'</td><td>'+places+'</td></tr>';}).join('')+'</tbody></table><div class="unote">Privileges that come through a role are listed under the role. Click an account to open it in Users.</div>';
 box.querySelectorAll('.acclink').forEach(a=>a.onclick=async e=>{e.preventDefault();const u=a.dataset.u,h=a.dataset.h;hide('mAccess');
  if(!$('mUsers').classList.contains('show'))await openUsers();
  const acct=_uaccts.find(x=>x.u===u&&(h===''||x.h===h));if(acct)usersSelect(acct.u,acct.h);});}

// ---- table designer ----
const DTYPES=['INT','BIGINT','TINYINT','SMALLINT','MEDIUMINT','DECIMAL','FLOAT','DOUBLE','BIT','BOOLEAN','CHAR','VARCHAR','TEXT','MEDIUMTEXT','LONGTEXT','DATE','DATETIME','TIMESTAMP','TIME','YEAR','JSON','BLOB','LONGBLOB','ENUM','BINARY','VARBINARY'];
let dOrig=null,dEdited=false;
// The designer shows a column as name / type / length / flags / default / comment, but a real
// column carries more than that: UNSIGNED, a character set and collation, ON UPDATE, INVISIBLE, a
// fractional-seconds precision, a DECIMAL scale, an ENUM's value list, and a default that may be an
// expression rather than a literal. None of those used to survive a MODIFY. The length box was
// filled from CHARACTER_MAXIMUM_LENGTH or NUMERIC_PRECISION alone, so editing nothing but the
// comment on a column rewrote it - measured on MySQL 8.0.46, from a comment-only edit:
//
//   DECIMAL(10,2)   12.34                       ->  DECIMAL(10,0)  12
//   INT UNSIGNED                                ->  INT (signed)
//   DATETIME(6)     2024-01-01 12:34:56.123456  ->  DATETIME       2024-01-01 12:34:56
//   latin1 text                                 ->  utf8mb4, re-encoded
//   ENUM('alpha','beta')                        ->  ENUM(5), a syntax error
//
// dColFromInfo() reads everything from COLUMN_TYPE and friends instead. What the form cannot show
// is kept on the row (keep) and written back unchanged, and only dropped where the user's own edit
// makes it meaningless - UNSIGNED on a column changed to VARCHAR, a character set on one changed
// to INT. Top-level and DOM-free so tests can drive them with real information_schema rows.
const D_TEXTY=/^(CHAR|VARCHAR|TINYTEXT|TEXT|MEDIUMTEXT|LONGTEXT|ENUM|SET)$/;
const D_NUMERIC=/^(TINYINT|SMALLINT|MEDIUMINT|INT|INTEGER|BIGINT|DECIMAL|NUMERIC|FLOAT|DOUBLE|REAL)$/;
const D_TEMPORAL=/^(DATETIME|TIMESTAMP)$/;
// row: COLUMN_NAME, DATA_TYPE, COLUMN_TYPE, IS_NULLABLE, COLUMN_DEFAULT, EXTRA, COLUMN_KEY,
//      COLUMN_COMMENT, CHARACTER_SET_NAME, COLLATION_NAME, GENERATION_EXPRESSION
// tableColl: the table's default collation. A column that merely inherits it gets no clause of its
// own, so SHOW CREATE TABLE - and Compare DB - still read it as inheriting after an edit.
function dColFromInfo(row,isMaria,tableColl){
 const [name,dataType,colType,nullable,rawDef,extraRaw,key,comment,cs,coll,genExpr]=row;
 const extra=extraRaw||'';
 const type=String(dataType).toUpperCase();
 // "decimal(10,2) unsigned zerofill", "enum('a)','b')", "bigint unsigned", "datetime(6)".
 // The greedy group runs to the LAST ')' that still leaves only modifiers after it, so a ')'
 // inside an ENUM value does not end the list early.
 const m=/^[a-z ]+?(?:\((.*)\))?((?:\s+(?:unsigned|signed|zerofill))*)\s*$/i.exec(String(colType||''));
 const len=m&&m[1]!=null?m[1]:'';
 const mods=m&&m[2]?m[2].trim().toUpperCase():'';
 // Defaults. MySQL gives a literal unquoted and marks an expression with DEFAULT_GENERATED;
 // MariaDB quotes a literal, spells an explicit NULL default as the word NULL, and gives an
 // expression bare. defShown is what the form displays; defSql is the exact SQL to write back
 // while the displayed value is left alone.
 let defShown='',defSql=null;
 if(rawDef!=null){
  const v=String(rawDef);
  if(isMaria){
   if(v==='NULL'){defShown='NULL';defSql='NULL';}
   else if(/^'[\s\S]*'$/.test(v)){defShown=v.slice(1,-1).replace(/''/g,"'").replace(/\\\\/g,'\\');defSql=v;}
   else{defShown=v;defSql=v;}
  } else {
   defShown=v;
   // information_schema escapes the quotes of a string inside an expression default -
   // concat(_utf8mb4\'a\',...) - and written back like that the MODIFY failed.
   if(/DEFAULT_GENERATED/i.test(extra))defSql=/^current_timestamp(\(\d*\))?$/i.test(v)?v:'('+v.replace(/\\(['\\])/g,'$1')+')';
   else if(/^b'[01]*'$/i.test(v)||/^0x[0-9a-f]*$/i.test(v))defSql=v;
   // MySQL 5.7 has no DEFAULT_GENERATED: its CURRENT_TIMESTAMP default was quoted as text, and the
   // MODIFY failed with "Invalid default value".
   else if(/^(TIMESTAMP|DATETIME)$/.test(type)&&/^current_timestamp(\(\d*\))?$/i.test(v))defSql=v;
   else defSql=strLit(v);
  }
 }
 const onUp=/on update\s+(\S+)/i.exec(extra);
 const generated=/GENERATED/i.test(extra.replace(/DEFAULT_GENERATED/ig,''));
 const col={name,type,len,nn:nullable==='NO',def:defShown,ai:/auto_increment/i.test(extra),pk:key==='PRI',comment:comment||''};
 const inherits=!!coll&&coll===tableColl;
 col.keep={origName:name,origType:type,origLen:len,mods,cs:inherits?'':(cs||''),coll:inherits?'':(coll||''),onUpdate:onUp?onUp[1]:'',
   invisible:/\bINVISIBLE\b/i.test(extra),defShown,defSql,generated,genExpr:genExpr||''};
 return col;
}
// Each column's line in SHOW CREATE TABLE, keyed by lower-cased name.
function dColumnLines(create){const out={};
 String(create).split(/\r?\n/).forEach(l=>{const t=l.trim();if(!t.startsWith('`'))return;
  let name='',i=1;for(;i<t.length;i++){if(t[i]==='`'){if(t[i+1]==='`'){name+='`';i++;continue;}break;}name+=t[i];}
  if(i<t.length)out[name.toLowerCase()]=t.replace(/,$/,'');});
 return out;}
function dKeepFromCreate(col,line){if(!line||!col.keep)return;
 const bare=sqlBlankStringsAndComments(line);
 const at=bare.search(/\sCHECK\s*\((?![\s\S]*\sCHECK\s*\()/i);
 if(at>=0){let d=0,ok=true;const open=bare.indexOf('(',at);for(let i=open;i<bare.length;i++){if(bare[i]==='(')d++;else if(bare[i]===')'){d--;if(d===0){ok=!bare.slice(i+1).trim();break;}}}
  if(ok&&d===0)col.keep.check=line.slice(at).trim();}
 const sr=/\/\*!80003 SRID (\d+) \*\//.exec(line);if(sr)col.keep.srid=sr[1];}
function colDef(c){
 const k=c.keep||{};
 let s=qid(c.name)+' '+c.type;if(c.len)s+='('+c.len+')';
 if(k.mods&&D_NUMERIC.test(c.type))s+=' '+k.mods;
 if(k.cs&&D_TEXTY.test(c.type))s+=' CHARACTER SET '+k.cs+(k.coll?' COLLATE '+k.coll:'');
 if(c.nn)s+=' NOT NULL';if(c.ai)s+=' AUTO_INCREMENT';
 // An untouched default is written back exactly as it was read - including an empty-string
 // default, which the form cannot tell apart from "no default" by looking at the box.
 // DEFAULT NULL is left out of a NOT NULL column: MariaDB reports a nullable column's default as the
 // word NULL, and ticking NOT NULL then wrote NOT NULL DEFAULT NULL, which the server refuses.
 if(k.defSql!=null&&c.def===k.defShown){if(!(c.nn&&/^NULL$/i.test(k.defSql)))s+=' DEFAULT '+k.defSql;}
 // A typed default is SQL where it can only be SQL - NULL, an expression in brackets such as
 // (CURDATE()) or (uuid()), and for a column that is not text a number, TRUE/FALSE, CURRENT_TIMESTAMP,
 // b'101' or 0x41 - and a string otherwise. A text column's "007" used to go in as the number 7,
 // stored as '7', and an expression or bit literal became a quoted string: an error on a DATE or
 // BIT column, a wrong literal default on a VARCHAR.
 else if(c.def!==''&&c.def!=null){const d=String(c.def),texty=D_TEXTY.test(c.type);
  const asSql=/^NULL$/i.test(d)||/^\([\s\S]*\)$/.test(d)||(!texty&&/^(CURRENT_TIMESTAMP(\(\d*\))?|TRUE|FALSE|-?\d+(\.\d+)?([eE][+-]?\d+)?|[bB]'[01]*'|0x[0-9A-Fa-f]+)$/i.test(d));
  if(!(c.nn&&/^NULL$/i.test(d)))s+=' DEFAULT '+(asSql?d:strLit(d));}
 if(k.onUpdate&&D_TEMPORAL.test(c.type))s+=' ON UPDATE '+k.onUpdate;
 if(k.invisible)s+=' INVISIBLE';
 const sameType=k.origType!=null&&c.type===k.origType;
 if(k.srid&&sameType)s+=' /*!80003 SRID '+k.srid+' */';
 if(c.comment)s+=' COMMENT '+strLit(c.comment);
 if(k.check&&sameType)s+=' '+k.check;
 return s;}
// The ALTER for a set of edited columns against what was read. A row keeps the name it was read
// with, so renaming one is a CHANGE COLUMN; it used to be DROP COLUMN old + ADD COLUMN new, which
// throws away every value in it.
function dAlterSql(orig,cols,tbl){
 const alt=[],notes=[];
 const seen=new Set();
 const same=(o,c)=>JSON.stringify({t:o.type,l:''+o.len,nn:o.nn,ai:o.ai,d:o.def,cm:o.comment})===JSON.stringify({t:c.type,l:''+c.len,nn:c.nn,ai:c.ai,d:c.def,cm:c.comment});
 cols.forEach(c=>{
  const on=c.keep&&c.keep.origName;
  const o=on!=null?orig.find(x=>x.name===on):null;
  if(!o){alt.push('ADD COLUMN '+colDef(c));return;}
  seen.add(o.name);
  const renamed=c.name!==o.name;
  if(!renamed&&same(o,c))return;
  // A generated column's expression comes back from information_schema with its quoting
  // mangled on some versions, so rewriting it is not safe. Leave it, and say so.
  if(o.keep&&o.keep.generated){notes.push('-- '+qid(o.name)+' is a generated column; change it with SQL, not the designer (left unchanged)');return;}
  alt.push((renamed?'CHANGE COLUMN '+qid(o.name)+' ':'MODIFY COLUMN ')+colDef(c));
 });
 orig.filter(o=>!seen.has(o.name)).forEach(o=>alt.push('DROP COLUMN '+qid(o.name)));
 // The key keeps the order it has: its own columns first, as they were, then any newly ticked.
 const was=c=>(c.keep&&c.keep.origName)||c.name,oldOrder=orig.pkOrder||orig.filter(c=>c.pk).map(c=>c.name);
 const ticked=cols.filter(c=>c.pk),pkCols=[...oldOrder.map(n=>ticked.find(c=>was(c)===n)).filter(Boolean),...ticked.filter(c=>!oldOrder.includes(was(c)))];
 const oldPk=oldOrder.join(','),newPk=pkCols.map(was).join(',');
 if(oldPk!==newPk){if(oldPk)alt.push('DROP PRIMARY KEY');if(pkCols.length)alt.push('ADD PRIMARY KEY ('+pkCols.map(c=>qid(c.name)).join(',')+')');}
 if(alt.length)notes.push(...dTsNotes(cols.filter(c=>{const on=c.keep&&c.keep.origName;const o=on!=null?orig.find(x=>x.name===on):null;return !o||alt.some(a=>a.includes(qid(c.name)));})));
 const head=notes.length?notes.join('\n')+'\n':'';
 return alt.length?head+'ALTER TABLE '+tbl+'\n  '+alt.join(',\n  ')+';':head+'-- no changes detected';
}
// With explicit_defaults_for_timestamp OFF (MariaDB's default before 10.10, and a setting some MySQL
// servers keep), a TIMESTAMP NOT NULL written without a default is given DEFAULT CURRENT_TIMESTAMP ON
// UPDATE CURRENT_TIMESTAMP when it is the table's first - measured on MySQL 8: a MODIFY that only
// changed the comment added both. Nothing in the column definition can say "no default" there, so
// the generated SQL says what will happen.
async function dReadTimestampMode(){window._dTsAuto=false;try{const r=await api('/api/query',{sql:'SELECT @@SESSION.explicit_defaults_for_timestamp'});if(r&&r.ok&&r.rows.length)window._dTsAuto=(String(r.rows[0][0])==='0'||String(r.rows[0][0]).toUpperCase()==='OFF');}catch(e){}}
function dTsNotes(cols){if(typeof window==='undefined'||!window._dTsAuto)return [];
 return cols.filter(c=>c.type==='TIMESTAMP'&&c.nn&&(c.def==null||c.def==='')&&!(c.keep&&c.keep.onUpdate)&&!(c.keep&&c.keep.defSql!=null&&c.def===c.keep.defShown))
  .map(c=>'-- explicit_defaults_for_timestamp is OFF on this server: '+qid(c.name)+' as written here may be given DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP. Give it a default to prevent that.');}
async function designTable(name,db){dEdited=false;await dReadTimestampMode();db=db||curSchema||'';$('dSchema').value=db;$('dName').value=name||'';$('dCols').innerHTML='';$('dLog').textContent='';dOrig=null;
 if(name){$('dTitle').textContent='Alter table';$('dMode').textContent='(existing - generates ALTER)';
   const r=await api('/api/query',{sql:"SELECT COLUMN_NAME,DATA_TYPE,COLUMN_TYPE,IS_NULLABLE,COLUMN_DEFAULT,EXTRA,COLUMN_KEY,COLUMN_COMMENT,CHARACTER_SET_NAME,COLLATION_NAME,GENERATION_EXPRESSION FROM information_schema.COLUMNS WHERE TABLE_SCHEMA="+lit(db)+" AND TABLE_NAME="+lit(name)+" ORDER BY ORDINAL_POSITION"});
   const tc=await api('/api/query',{sql:"SELECT TABLE_COLLATION FROM information_schema.TABLES WHERE TABLE_SCHEMA="+lit(db)+" AND TABLE_NAME="+lit(name)});
   const tableColl=tc.ok&&tc.rows[0]?tc.rows[0][0]:null;
   // What information_schema does not say about a column, the server's own CREATE line does: a
   // column-level CHECK (MariaDB writes one for every JSON column, json_valid) and MySQL's SRID. A
   // MODIFY built without them dropped both - invalid JSON was accepted afterwards, and a spatial
   // column took any SRID - so they are kept from that line while the column keeps its type.
   const sc=await api('/api/query',{sql:'SHOW CREATE TABLE '+qid(db)+'.'+qid(name)});
   const lines=dColumnLines(sc.ok&&sc.rows[0]?String(sc.rows[0][1]||''):'');
   // The primary key as the table has it, in its own order. COLUMN_KEY says PRI for a UNIQUE NOT NULL
   // column too when there is no primary key, which showed it ticked - and unticking or adding
   // another wrote DROP PRIMARY KEY on a table that had none. And the key was rebuilt in column
   // order, so PRIMARY KEY (b,a) became (a,b,...) the moment another column joined it.
   const pkr=await api('/api/query',{sql:"SELECT COLUMN_NAME FROM information_schema.KEY_COLUMN_USAGE WHERE TABLE_SCHEMA="+lit(db)+" AND TABLE_NAME="+lit(name)+" AND CONSTRAINT_NAME='PRIMARY' ORDER BY ORDINAL_POSITION"});
   const pkOrder=pkr.ok?pkr.rows.map(x=>String(x[0])):null;
   dOrig=[];if(pkOrder)dOrig.pkOrder=pkOrder;
   if(r.ok)r.rows.forEach(row=>{const col=dColFromInfo(row,!!window.mariadb,tableColl);if(pkOrder)col.pk=pkOrder.includes(col.name);dKeepFromCreate(col,lines[String(col.name).toLowerCase()]);dOrig.push(col);dAddCol(col);});
   else{$('dLog').textContent='Could not read the table: '+r.error;}
 } else {$('dTitle').textContent='Create table';$('dMode').textContent='(new - generates CREATE)';dAddCol({name:'id',type:'INT',len:'',nn:true,ai:true,pk:true,def:null,comment:''});dAddCol({name:'',type:'VARCHAR',len:'255',nn:false,ai:false,pk:false,def:null,comment:''});}
 dGen();show('mDesign');}
function dAddCol(c){c=c||{name:'',type:'VARCHAR',len:'255',nn:false,ai:false,pk:false,def:null,comment:''};const tr=document.createElement('tr');
 // A type the list does not carry (SET, TINYTEXT, GEOMETRY...) must still be offered, or the
 // select falls back to its first entry and the column is silently read back as INT.
 const types=DTYPES.includes(c.type)?DTYPES:DTYPES.concat([c.type]);
 tr.innerHTML='<td><input class="dn" value="'+esc(c.name)+'"></td><td><select class="dt">'+types.map(t=>'<option'+(t===c.type?' selected':'')+'>'+esc(t)+'</option>').join('')+'</select></td>'+
  '<td><input class="dl" value="'+esc(c.len==null?'':c.len)+'"></td><td><input type="checkbox" class="dnn"'+(c.nn?' checked':'')+'></td>'+
  '<td><input type="checkbox" class="dai"'+(c.ai?' checked':'')+'></td><td><input type="checkbox" class="dpk"'+(c.pk?' checked':'')+'></td>'+
  '<td><input class="dd" value="'+esc(c.def==null?'':c.def)+'"></td><td><input class="dc" value="'+esc(c.comment||'')+'"></td>'+
  '<td><button class="sm" title="Remove this column" onclick="this.closest(\'tr\').remove();dGen()">&times;</button></td>';
 tr._keep=c.keep||null;
 if(c.keep){const hint=[c.keep.mods,c.keep.cs&&('CHARACTER SET '+c.keep.cs),c.keep.onUpdate&&('ON UPDATE '+c.keep.onUpdate),c.keep.invisible&&'INVISIBLE',c.keep.generated&&'GENERATED'].filter(Boolean).join(', ');if(hint)tr.title='Kept as is: '+hint;}
 $('dCols').appendChild(tr);tr.querySelectorAll('input,select').forEach(el=>el.addEventListener('change',dGen));}
function dMark(){dEdited=true;$('dEditNote').textContent='✎ manually edited - auto-update paused; use Regenerate to rebuild';}
// Names lose trailing spaces only - a name cannot end in one, but may begin with one, and trimming
// both ends renamed a column called " a" to "a" on the next Apply. A comment is kept exactly as it
// is: trimmed, it no longer matched the table's own, and any change to that column rewrote it.
function dReadCols(){return [...$('dCols').children].map(tr=>({name:tr.querySelector('.dn').value.replace(/\s+$/,''),type:tr.querySelector('.dt').value,len:tr.querySelector('.dl').value.trim(),nn:tr.querySelector('.dnn').checked,ai:tr.querySelector('.dai').checked,pk:tr.querySelector('.dpk').checked,def:tr.querySelector('.dd').value,comment:tr.querySelector('.dc').value,keep:tr._keep||null})).filter(c=>c.name.trim());}
function dGen(force){if(dEdited&&!force)return;const db=$('dSchema').value.replace(/\s+$/,''),name=$('dName').value.replace(/\s+$/,'');const cols=dReadCols();const pk=cols.filter(c=>c.pk).map(c=>qid(c.name));
 if(!name){$('dSql').value='-- enter a table name';return;}const tbl=qid(db)+'.'+qid(name);
 if(!dOrig){const tsn=dTsNotes(cols);let s=(tsn.length?tsn.join('\n')+'\n':'')+'CREATE TABLE '+tbl+' (\n  '+cols.map(colDef).join(',\n  ');if(pk.length)s+=',\n  PRIMARY KEY ('+pk.join(',')+')';s+='\n);';$('dSql').value=s;dEdited=false;$('dEditNote').textContent='';return;}
 $('dSql').value=dAlterSql(dOrig,cols,tbl);dEdited=false;$('dEditNote').textContent='';}
async function dApply(){if(roBlock())return;const sql=$('dSql').value;$('dLog').textContent='Applying...';const r=await api('/api/script',{sql,db:curSchema});if(r.ok){$('dLog').textContent='Applied OK.';log('DESIGN OK');if(curSchema)loadObjects(curSchema);}else{const _n=ddlFailureNote(r.error,sql);$('dLog').textContent=_n;log('DESIGN error: '+_n);}}

// ---- export/import ----
// [key, label, default, what it does, group, the mysqldump option]. Include is always on show; the
// other groups sit under Advanced options, where their defaults rarely need changing.
const EXPOPTS=[
 ['routines','Procedures and functions',1,'Include stored procedures and functions in the dump.','Include','--routines'],
 ['triggers','Triggers',1,'Include table triggers in the dump.','Include','--triggers'],
 ['events','Events',1,'Include scheduled events in the dump.','Include','--events'],
 ['createdb','CREATE DATABASE',1,'Include CREATE DATABASE and USE so the dump can rebuild the database anywhere.','Include','--no-create-db when off'],
 ['adddropdb','DROP DATABASE first',1,'Write DROP DATABASE before CREATE so a re-import replaces it cleanly.','Include','--add-drop-database'],
 ['adddroptb','DROP TABLE first',1,'Write DROP TABLE before each CREATE so a re-import replaces it cleanly.','Include','--add-drop-table'],
 ['nodefiner','Leave out DEFINER',1,'Strip DEFINER=user@host from views, triggers, procedures and events: without this, restoring on a server where that exact account does not exist fails or warns on every one of them.','Include',''],
 ['hexblob','Binary columns as hex',1,'Dump binary/BLOB columns as hexadecimal (e.g. abc becomes 0x616263).','Data','--hex-blob'],
 ['tzutc','Times in UTC',1,'Add SET TIME_ZONE=UTC so TIMESTAMP values restore the same in any timezone.','Data','--tz-utc'],
 ['extinsert','Many rows per INSERT',1,'Pack many rows into each INSERT: smaller files, much faster import.','Data','--extended-insert'],
 ['complete','Column names in each INSERT',0,'Write column names in every INSERT: safer if column order differs, but larger files.','Data','--complete-insert'],
 ['singletx','One consistent snapshot',1,'Take a consistent snapshot without locking tables (recommended for InnoDB).','Performance','--single-transaction'],
 ['quick','Stream rows',1,'Stream rows instead of buffering the whole table: needed for very large tables.','Performance','--quick'],
 ['diskeys','Keys off while loading',1,'Disable indexes during load and rebuild them after: faster import.','Performance','--disable-keys'],
 ['compress','Compress the connection',0,'Compress the client/server connection during the dump (more CPU, less network).','Performance','--compress'],
 ['notablespaces','Leave out TABLESPACE',1,'Skip TABLESPACE clauses: avoids errors when the target server lacks them.','Compatibility','--no-tablespaces'],
 ['gtid','Leave out GTID info',0,'Do not write GTID replication info: avoids import errors on non-GTID servers.','Compatibility','--set-gtid-purged=OFF'],
 ['colstats','No column statistics',0,'Disable column statistics: fixes an error when a MySQL 8 client dumps MariaDB.','Compatibility','--column-statistics=0']
];
// openExport() rebuilds the option checkboxes every time it runs, so each one came back at
// its EXPOPTS default and any choice the user had made was silently discarded the next time
// the dialog opened. Unchecking "routines" and "events" then exporting again quietly dumped
// them anyway - and the same applied to add-drop-table, which is a good deal worse to get
// wrong by surprise. Remember the choices and put them back after the rebuild.
function expOptsLoad(){ try{ const v=JSON.parse(localStorage.getItem('nobsExpOpts')||'{}'); return (v&&typeof v==='object')?v:{}; }catch(e){ return {}; } }
function expOptsSave(){ const o={}; EXPOPTS.forEach(([k])=>{const el=$('eo_'+k); if(el)o[k]=!!el.checked;}); try{ localStorage.setItem('nobsExpOpts',JSON.stringify(o)); }catch(e){} }
function expOptsRestore(){
 const saved=expOptsLoad();
 EXPOPTS.forEach(([k])=>{
  const el=$('eo_'+k); if(!el)return;
  if(Object.prototype.hasOwnProperty.call(saved,k)) el.checked=!!saved[k];
  el.addEventListener('change',expOptsSave);
 });
}
async function openExport(preselect){const r=await api('/api/schemas');const box=$('expDbs');box.innerHTML='';if(r.ok)r.schemas.forEach(s=>{const safe=s.name.replace(/[^A-Za-z0-9]/g,'_');const dbAttr=esc(s.name).replace(/\\/g,'\\\\').replace(/\x27/g,'\\x27').replace(/\n/g,'\\n').replace(/\r/g,'\\r');box.innerHTML+='<div class="expdbrow"><span class="exptoggle" id="expx_'+safe+'" onclick="expTables(\''+dbAttr+'\',\''+safe+'\')" title="Show tables to exclude">\u25B8</span><label class="ck" style="display:inline-flex"><input type="checkbox" class="expdb" value="'+esc(s.name)+'" onchange="expDbToggle(\''+safe+'\',this.checked)"> '+esc(s.name)+'</label><div class="exptbls" id="expt_'+safe+'" style="display:none"></div></div>';});const ob=$('expOpts'),adv=$('expOptsAdv');
const ck=([k,l,d,t,g,f])=>'<label class="ck" title="'+esc(t+(f?'\n(mysqldump '+f+')':''))+'"><input type="checkbox" id="eo_'+k+'" '+(d?'checked':'')+'> '+esc(l)+'</label>';
ob.innerHTML=EXPOPTS.filter(o=>o[4]==='Include').map(ck).join('');
adv.innerHTML=['Data','Performance','Compatibility'].map(g=>'<div class="xgrp">'+g+'</div>'+EXPOPTS.filter(o=>o[4]===g).map(ck).join('')).join('');
expOptsRestore();
$('expWhatAll').checked=true;expWhatChanged();
try{$('expAdv').open=localStorage.getItem('nobsExpAdv')==='1';}catch(e){}
expSyncFilenameField();
expApplyDumpFlavor();
if(preselect&&preselect.db){
  document.querySelectorAll('.expdb').forEach(cb=>{cb.checked=(cb.value===preselect.db);});
  if(preselect.table){
    const safe=preselect.db.replace(/[^A-Za-z0-9]/g,'_');
    await expTables(preselect.db,safe);
    document.querySelectorAll('#expt_'+safe+' .exptbl').forEach(cb=>{cb.checked=(cb.value===preselect.table);});
    if($('eo_routines'))$('eo_routines').checked=false;
    if($('eo_events'))$('eo_events').checked=false;
  }
}
show('mExport');}
// What goes in the dump. Data only leaves out all that creates or drops, so those choices are
// greyed and not sent; structure only greys what shapes the rows. Each opening starts at structure
// and data, so a backup never goes out without its rows because of an earlier export's choice.
const EXP_NOT_FOR={data:['routines','triggers','events','createdb','adddropdb','adddroptb'],structure:['hexblob','extinsert','complete','diskeys','quick']};
function expWhat(){return $('expWhatStructure').checked?'structure':$('expWhatData').checked?'data':'all';}
function expWhatChanged(){const off=EXP_NOT_FOR[expWhat()]||[];EXPOPTS.forEach(([k])=>{if(k in MYSQL_ONLY_EXPOPTS)return;const el=$('eo_'+k);if(!el)return;const no=off.includes(k);el.disabled=no;const l=el.closest('label');if(l)l.classList.toggle('xoff',no);});}
function expAdvToggled(){try{localStorage.setItem('nobsExpAdv',$('expAdv').open?'1':'0');}catch(e){}}
function expAll(v){[...document.querySelectorAll('.expdb')].forEach(c=>c.checked=v);[...document.querySelectorAll('.exptbl')].forEach(c=>c.checked=v);}
function expSyncFilenameField(){const row=$('expFilenameRow');if(row)row.style.display=$('expSingle').checked?'flex':'none';expUpdateFilenamePreview();}
// Its own row (matching Folder's label/width/casing) instead of squeezed into the dense options
// row above at 120px wide - plus a live preview of the actual resulting file name, since
// "timestamp" silently changes what gets written and a plain text box alone doesn't show that.
function expUpdateFilenamePreview(){const el=$('expFilenamePreview');if(!el)return;const inp=$('expFilename');const base=(inp.value||'').trim()||'all_selected';const stamp=$('expStamp').checked?'_'+expTimestampSample():'';const text='\u2192 '+base+stamp+'.sql';el.textContent=text;el.title=text;
 // Quiet unless you're actually closing in on the limit - a short, everyday filename shouldn't
 // have to share the row with a running character count.
 const cnt=$('expFilenameCount');if(cnt){const len=inp.value.length,max=inp.maxLength;
  if(len>=max-20){cnt.style.display='';cnt.textContent=len+'/'+max;cnt.style.color=(len>=max)?'var(--log-warn)':'';}
  else{cnt.style.display='none';}
 }}
function expTimestampSample(){const d=new Date();const p=n=>String(n).padStart(2,'0');return d.getFullYear()+p(d.getMonth()+1)+p(d.getDate())+'_'+p(d.getHours())+p(d.getMinutes())+p(d.getSeconds());}
// A few export options only exist on one mysqldump flavor: --set-gtid-purged is MySQL 5.6+
// only, --column-statistics is MySQL 8+ only - MariaDB's mysqldump has neither, and checking
// either against it aborts the WHOLE export with "unknown variable". Grey them out up front
// (based on tools_status's one-time `--version` check) instead of letting that be a surprise
// mid-export - the backend also has a friendlier error message as a fallback for anything this
// doesn't catch (an unusual custom mysqldump path, a version too old for a flag, etc).
const MYSQL_ONLY_EXPOPTS={
 gtid:'set-gtid-purged is MySQL 5.6+ only - not supported by MariaDB\u2019s mysqldump.',
 colstats:'column-statistics is MySQL 8+ only - not supported by MariaDB\u2019s mysqldump.'
};
async function expApplyDumpFlavor(){
 // The dump tool depends on the server (MySQL's own for a MySQL server, when there is one), so
 // ask for the connected one; the global status is the fallback for a backend that cannot say.
 let r=null; try{ r=await api('/api/tools-for-conn'); }catch(e){}
 let isMariaDb;
 if(r&&r.ok&&r.mysqldumpIsMariadb!=null){ isMariaDb=r.mysqldumpIsMariadb===true; }
 else{ try{ r=await api('/api/tools-status'); }catch(e){ return; } isMariaDb=!!(r&&r.ok&&r.mysqldump_is_mariadb===true); }
 Object.keys(MYSQL_ONLY_EXPOPTS).forEach(k=>{
  const el=$('eo_'+k); if(!el)return;
  const lbl=el.closest('label');
  let note=lbl&&lbl.querySelector('.expoptsdis');
  if(isMariaDb){
   el.disabled=true; el.checked=false;
   if(lbl){ lbl.title='Not supported: '+MYSQL_ONLY_EXPOPTS[k]; lbl.style.opacity='.55';
    if(!note){ note=document.createElement('span'); note.className='expoptsdis'; note.style.cssText='font-size:10px;color:var(--del);margin-left:4px'; note.textContent='(MySQL only)'; lbl.appendChild(note); } }
  } else {
   el.disabled=false;
   if(lbl)lbl.style.opacity='';
   if(note)note.remove();
  }
 });
}
async function expTables(db,safe){const c=$('expt_'+safe);if(!c)return;const cx=$('expx_'+safe);if(c.style.display==='none'){c.style.display='block';if(cx)cx.textContent='\u25BE';if(!c.dataset.loaded){c.innerHTML='<span class="muted" style="font-size:11px">Loading\u2026</span>';const q=await api('/api/query',{sql:'SELECT TABLE_NAME FROM information_schema.TABLES WHERE TABLE_SCHEMA='+lit(db)+' ORDER BY TABLE_NAME'});if(!q.ok){c.innerHTML='<span class="muted" style="font-size:11px">'+esc(q.error||'Could not list tables')+'</span>';return;}if(!q.rows.length){c.innerHTML='<span class="muted" style="font-size:11px">(no tables)</span>';c.dataset.loaded='1';return;}const dbCk=document.querySelector('.expdb[value="'+CSS.escape(db)+'"]');const on=dbCk?dbCk.checked:true;let h='<div class="muted" style="font-size:11px;margin:1px 0 3px">Untick a table to exclude it from the export:</div>';q.rows.forEach(r=>{const tn=r[0];h+='<label class="ck" style="font-size:12px"><input type="checkbox" class="exptbl" data-db="'+esc(db)+'" value="'+esc(tn)+'" '+(on?'checked':'')+'> '+esc(tn)+'</label>';});c.innerHTML=h;c.dataset.loaded='1';}}else{c.style.display='none';if(cx)cx.textContent='\u25B8';}}
function expDbToggle(safe,on){document.querySelectorAll('#expt_'+safe+' .exptbl').forEach(c=>{c.checked=on;});}
async function runExport(){const dbs=[...document.querySelectorAll('.expdb:checked')].map(c=>c.value);
const tables=[...document.querySelectorAll('.exptbl:checked')].map(c=>c.dataset.db+'.'+c.value);

// Allow either databases OR tables to be selected
if(!dbs.length && !tables.length){
    toast('Select at least one database or table.',true);
    return;
}

// A database whose tables are ticked goes in with those tables (its unticked ones are left out below),
// whether or not another database is ticked as well. Tables ticked under an unticked database used to
// be dropped without a word as soon as any database box was ticked, and a database name with a dot
// in it was cut at the dot. The name comes from the box itself.
[...new Set([...document.querySelectorAll('.exptbl:checked')].map(c => c.dataset.db))].forEach(d => { if (!dbs.includes(d)) dbs.push(d); });const o={charset:$('expCharset').value};EXPOPTS.forEach(([k])=>o[k]=$('eo_'+k).checked);o.what=expWhat();if(o.what==='data')EXP_NOT_FOR.data.forEach(k=>o[k]=false);o.maxpacket=$('expMaxPacket').value.trim();let mode='table';if($('expPer').checked)mode='db';else if($('expSingle').checked)mode='single';const excludes=[...document.querySelectorAll('.exptbl:not(:checked)')].filter(c=>dbs.includes(c.dataset.db)).map(c=>c.dataset.db+'.'+c.value);
 if(!$('expStamp').checked){
   const chk=await api('/api/browse',{path:$('expFolder').value,filter:'*.sql',dirsOnly:false});
   if(chk.ok && chk.files && chk.files.length>0){
     if(!(await ask('The export folder already contains '+chk.files.length+' .sql file(s), and "timestamp" is unchecked. Matching filenames will be overwritten. Continue?')))return;
   }
 }
 $('expLog').textContent='';
 let label='Exporting '+dbs.length+' database'+(dbs.length===1?'':'s');
 if(mode==='table'){try{const cq=await api('/api/query',{sql:"SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_TYPE IN ('BASE TABLE','SYSTEM VERSIONED') AND TABLE_SCHEMA IN ("+dbs.map(lit).join(',')+")"});if(cq.ok&&cq.rows.length){label+=' (~'+fmtCount(cq.rows[0][0])+' tables)';}}catch(e){}}
 const jobId=(crypto.randomUUID?crypto.randomUUID():('j'+Date.now()+Math.random()));
 progStart('exp',label,jobId);
 const r=await api('/api/export',{dbs,options:o,folder:$('expFolder').value,mode:mode,filename:$('expFilename').value.trim(),stamp:$('expStamp').checked,excludes:excludes,jobId:jobId});
 progStop('exp');
 if(r.cancelled){log('Export cancelled.');}
 if(!r.ok){showToolError('expLog','mExport',r.error);log('Export error: '+r.error);return;}
